package adamski.domain.balance;

import adamski.domain.ItemQuantities;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;
import lombok.Value;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Whether you have enough secondaries for the planned recipe runs.
 * <p>
 * Holds one {@link BalanceEntry} per secondary the runs need, plus totals across them. Secondaries
 * nothing needs are left out.
 */
@Getter
@EqualsAndHashCode
@ToString
public final class SecondaryBalance {
    private final List<BalanceEntry> entries;
    private final ItemQuantities demanded;
    private final ItemQuantities net;

    public SecondaryBalance(List<BalanceEntry> entries) {
        this.entries = List.copyOf(entries);

        final Map<Integer, Double> demanded = new HashMap<>();
        final Map<Integer, Double> net = new HashMap<>();
        for (BalanceEntry entry : this.entries) {
            demanded.put(entry.getSecondaryItemId(), entry.getQtyDemanded());
            net.put(entry.getSecondaryItemId(), entry.net());
        }

        this.demanded = ItemQuantities.of(demanded);
        this.net = ItemQuantities.of(net);
    }

    /**
     * One secondary's balance, and where the supply comes from.
     * <p>
     * For example, crushed bird nests: 10 needed, 3 held, 4 made from bird nests. Net is -3.
     */
    @Value
    public static class BalanceEntry {
        int secondaryItemId;
        double qtyDemanded;
        double qtyHeld;

        /**
         * One per chain that makes the secondary, in chain order.
         * <p>
         * Empty when no chain makes it, or when "Count secondaries made by rows" is off.
         */
        List<ChainContribution> chainContributions;

        /**
         * One per precursor held, in table order.
         * <p>
         * Empty when none are held, or when "Count secondary precursors" is off.
         */
        List<PrecursorContribution> precursorContributions;

        public double totalFromChains() {
            return chainContributions.stream().mapToDouble(ChainContribution::getMakes).sum();
        }

        public double totalFromPrecursors() {
            return precursorContributions.stream().mapToDouble(PrecursorContribution::getMakes).sum();
        }

        public double net() {
            return qtyHeld + totalFromChains() + totalFromPrecursors() - qtyDemanded;
        }
    }

    /**
     * How much of a secondary one chain will make - 30 super attacks from the irit row, say.
     */
    @Value
    public static class ChainContribution {
        int rootItemId;
        double makes;
    }

    /**
     * How much of a secondary one held precursor will make - 10 lava scales making 45 shards, say.
     */
    @Value
    public static class PrecursorContribution {
        int precursorItemId;
        double held;
        double makes;
    }
}

package adamski.domain.balance;

import adamski.domain.result.ChainResult;
import adamski.domain.ItemQuantities;
import adamski.domain.SecondaryPrecursor;
import adamski.domain.balance.SecondaryBalance.ChainContribution;
import adamski.domain.balance.SecondaryBalance.PrecursorContribution;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * What the chains' planned runs will cost in secondaries, netted against what is held - and,
 * optionally, against what other chains make and what precursors held would become.
 */
public final class SecondaryBalanceCalculator {
    private SecondaryBalanceCalculator() {
    }

    /**
     * @param chainResults         every chain's result - what they demand, and what they make
     * @param owned                what the player holds
     * @param chainProductsCounted whether what one chain makes counts towards another's secondaries
     * @param precursors           what can be turned into a secondary and counted as one - empty to
     *                             count none
     */
    public static SecondaryBalance calculate(List<ChainResult> chainResults, ItemQuantities owned,
                                             boolean chainProductsCounted, List<SecondaryPrecursor> precursors) {
        final ItemQuantities demanded = sumDemand(chainResults);
        final Map<Integer, List<ChainContribution>> chainContributionsBySecondary =
                chainProductsCounted ? chainContributionsBySecondary(chainResults) : Map.of();
        final Map<Integer, List<PrecursorContribution>> precursorContributionsBySecondary =
                precursorContributionsBySecondary(precursors, owned);

        final List<SecondaryBalance.BalanceEntry> entries = new ArrayList<>();
        demanded.forEach((secondaryItemId, required) -> entries.add(new SecondaryBalance.BalanceEntry(
                secondaryItemId, required, owned.get(secondaryItemId),
                chainContributionsBySecondary.getOrDefault(secondaryItemId, List.of()),
                precursorContributionsBySecondary.getOrDefault(secondaryItemId, List.of()))));

        return new SecondaryBalance(entries);
    }

    private static ItemQuantities sumDemand(List<ChainResult> chainResults) {
        ItemQuantities demanded = ItemQuantities.EMPTY;

        for (ChainResult chainResult : chainResults) {
            demanded = demanded.plus(chainResult.getSecondaryDemand());
        }

        return demanded;
    }

    /**
     * For each product, what each chain makes of it. Only what the runs make counts - banked stock
     * of a product is held, and counted as held. A chain making nothing, or none of its product, is
     * left out.
     */
    private static Map<Integer, List<ChainContribution>> chainContributionsBySecondary(List<ChainResult> chainResults) {
        final Map<Integer, List<ChainContribution>> contributions = new HashMap<>();

        for (ChainResult chainResult : chainResults) {
            if (chainResult.makesNothing() || chainResult.getOutputQuantity() <= 0) continue;

            contributions.computeIfAbsent(chainResult.getProductItemId(), id -> new ArrayList<>())
                    .add(new ChainContribution(chainResult.getRootItemId(), chainResult.getOutputQuantity()));
        }

        return contributions;
    }

    /**
     * For each secondary, what each held precursor makes of it. Precursors not held are left out.
     */
    private static Map<Integer, List<PrecursorContribution>> precursorContributionsBySecondary(
            List<SecondaryPrecursor> precursors, ItemQuantities owned) {
        final Map<Integer, List<PrecursorContribution>> contributions = new HashMap<>();

        for (SecondaryPrecursor precursor : precursors) {
            final double held = owned.get(precursor.getItemId());
            if (held <= 0) continue;

            contributions.computeIfAbsent(precursor.getSecondaryItemId(), id -> new ArrayList<>())
                    .add(new PrecursorContribution(precursor.getItemId(), held, held * precursor.getYield()));
        }

        return contributions;
    }
}

package adamski.domain.result;

import adamski.domain.Recipe;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The alchemist's amulet: what it multiplies each recipe's output by, and what that costs and could
 * be used on, once the chains are calculated.
 * <p>
 * Its chance is of one extra dose per potion, whatever the potion's size, so a run gains
 * chance / doses per potion of what it makes: a whole 3-dose potion gains 5%, an upgrade made in
 * 1-dose potions 15%.
 */
public final class AlchemistAmuletCalculator {
    private AlchemistAmuletCalculator() {
    }

    /**
     * @param dosesPerPotionByRecipeId the size of potion each recipe is made in, for those the amulet
     *                                 is used on
     * @return recipe id to what its output is multiplied by, for {@code RecipeModifiers.outputScaling}
     */
    public static Map<Integer, Double> factorsByRecipeId(Map<Integer, Integer> dosesPerPotionByRecipeId,
                                                         double extraDoseChance) {
        final Map<Integer, Double> factors = new HashMap<>();
        dosesPerPotionByRecipeId.forEach((recipeId, dosesPerPotion) ->
                factors.put(recipeId, 1 + extraDoseChance / dosesPerPotion));
        return factors;
    }

    /**
     * The extra doses the amulet makes, one charge each. A scaled run makes its base output times
     * the factor, so the amulet's share of it is 1 - 1 / factor.
     *
     * @param factorsByRecipeId as {@link #factorsByRecipeId} made them, for the chains given
     */
    public static double sumCharges(List<ChainResult> chainResults, Map<Integer, Double> factorsByRecipeId) {
        double charges = 0;

        for (ChainResult chain : chainResults) {
            for (RecipeRun run : chain.getRecipeRuns()) {
                final Double factor = factorsByRecipeId.get(run.getRecipe().getId());
                if (factor != null) charges += run.getOutputQuantity() * (1 - 1 / factor);
            }
        }

        return charges;
    }

    /**
     * @param dosesPerPotionOptionsByRecipeId the recipes the amulet works on and the sizes each can
     *                                        be made in
     * @param dosesPerPotionByRecipeId        the sizes chosen, for those it is used on
     * @return every recipe the chains run that the amulet works on, in the order the options are
     * listed
     */
    public static List<AlchemistAmuletOption> findOptions(List<ChainResult> chainResults,
                                                          Map<Integer, List<Integer>> dosesPerPotionOptionsByRecipeId,
                                                          Map<Integer, Integer> dosesPerPotionByRecipeId) {
        final Map<Integer, Recipe> recipesRun = new HashMap<>();
        for (ChainResult chain : chainResults) {
            for (RecipeRun run : chain.getRecipeRuns()) {
                if (run.getRuns() > 0) recipesRun.put(run.getRecipe().getId(), run.getRecipe());
            }
        }

        final List<AlchemistAmuletOption> options = new ArrayList<>();
        dosesPerPotionOptionsByRecipeId.forEach((recipeId, sizes) -> {
            final Recipe recipe = recipesRun.get(recipeId);
            if (recipe == null) return;

            options.add(new AlchemistAmuletOption(recipeId, recipe.getOutput().getItemId(), sizes,
                    dosesPerPotionByRecipeId.get(recipeId)));
        });

        return options;
    }
}

