package adamski.domain.result;

import adamski.domain.ItemQuantities;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;

/**
 * The final XP & output quantity produced by a chain of recipes.
 */
@Getter
@EqualsAndHashCode
@ToString
public final class ChainResult {
    private final int rootItemId;
    private final int productItemId;

    /**
     * Total XP sliced by the items in this chain.
     */
    private final List<ChainItemXp> itemContributions;

    /**
     * Total XP sliced by the recipes in this chain (excluding 0 xp recipes).
     */
    private final List<ChainRecipeXp> recipeContributions;

    private final double outputQuantity;

    /**
     * How much of the root item is held, in 1-dose units.
     */
    private final double rootQuantity;

    /**
     * Every run in the chain, from every item - a recipe reached by several items appears once for
     * each.
     */
    private final List<RecipeRun> recipeRuns;

    private final ItemQuantities secondaryDemand;

    private final double xp;

    public ChainResult(int rootItemId,
                       int productItemId,
                       List<ChainItemXp> itemContributions,
                       List<ChainRecipeXp> recipeContributions,
                       double outputQuantity,
                       ItemQuantities secondaryDemand,
                       double xp) {
        if (itemContributions.isEmpty())
            throw new IllegalArgumentException("a chain result needs at least one item contributing to it");

        this.rootItemId = rootItemId;
        this.productItemId = productItemId;
        this.itemContributions = List.copyOf(itemContributions);
        this.recipeContributions = List.copyOf(recipeContributions);
        this.outputQuantity = outputQuantity;
        this.rootQuantity = this.itemContributions.stream()
                .filter(contribution -> contribution.getItemId() == rootItemId)
                .mapToDouble(ChainItemXp::getQuantity)
                .sum();
        this.recipeRuns = this.itemContributions.stream()
                .flatMap(contribution -> contribution.getRuns().stream())
                .collect(Collectors.toUnmodifiableList());
        this.secondaryDemand = secondaryDemand;
        this.xp = xp;
    }

    /**
     * Whether the chain runs any of these recipes at all.
     */
    public boolean runsAnyOf(Collection<Integer> recipeIds) {
        return recipeRuns.stream().anyMatch(run -> run.getRuns() > 0 && recipeIds.contains(run.getRecipe().getId()));
    }

    /**
     * Whether the chain ends where it starts - told to stop at its root, so it runs no recipes.
     */
    public boolean makesNothing() {
        return productItemId == rootItemId;
    }
}

package adamski.domain.result;

import adamski.domain.Ingredient;
import adamski.domain.ItemQuantities;
import adamski.domain.Recipe;
import adamski.domain.route.RecipeChain;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Runs banked items against the recipes in each chain, calculating an XP & quantity result sliced by recipe and item.
 */
public final class ChainResultCalculator {
    private ChainResultCalculator() {
    }

    /**
     * @param chains recipe chains
     * @param owned  items the player owns
     * @return one result per chain, in the order the chains were given, with chains nothing is
     * banked against left out
     */
    public static List<ChainResult> calculate(List<RecipeChain> chains, ItemQuantities owned) {
        final List<ChainResult> results = new ArrayList<>(chains.size());

        for (RecipeChain chain : chains) {
            List<Integer> ownedItemsInChain = findOwnedItemsInChain(chain, owned);

            final List<ChainItemXp> itemContributions = new ArrayList<>();
            final Map<Integer, Double> xpByRecipeId = new HashMap<>();
            double totalXp = 0.0;
            final var allRuns = new ArrayList<RecipeRun>();

            for (Integer itemId : ownedItemsInChain) {
                final double quantity = owned.get(itemId);
                final List<RecipeRun> runs = cascade(itemId, quantity, chain);

                // A banked product makes nothing further, so it is left out. A root that makes
                // nothing has been told to stop, and is kept so its chain still has a row.
                if (runs.isEmpty() && itemId != chain.getRootItemId()) continue;

                double itemXp = 0;
                for (RecipeRun run : runs) {
                    final double xp = run.getRuns() * run.getRecipe().getXp();
                    itemXp += xp;
                    if (xp != 0) xpByRecipeId.merge(run.getRecipe().getId(), xp, Double::sum);
                }

                totalXp += itemXp;
                allRuns.addAll(runs);
                itemContributions.add(new ChainItemXp(itemId, quantity, runs, itemXp));
            }

            if (itemContributions.isEmpty()) continue;

            final List<ChainRecipeXp> recipeContributions = new ArrayList<>();

            for (Recipe recipe : chain.getRecipes()) {
                final Double xp = xpByRecipeId.get(recipe.getId());
                if (xp != null) recipeContributions.add(new ChainRecipeXp(recipe, xp));
            }

            results.add(new ChainResult(
                    chain.getRootItemId(),
                    chain.getProductItemId(),
                    itemContributions,
                    recipeContributions,
                    sumOutputQuantity(allRuns, chain.getProductItemId()),
                    sumSecondaryDemand(allRuns),
                    totalXp));
        }

        return results;
    }

    /**
     * Returns how many times each recipe runs when one banked item is fed along the chain from
     * where it sits, each output feeding the next.
     */
    static List<RecipeRun> cascade(int itemId, double quantity, RecipeChain chain) {
        final List<RecipeRun> runs = new ArrayList<>();

        if (quantity == 0) return runs;

        int currentItem = itemId;
        double held = quantity;

        for (Recipe recipe : chain.getRecipes()) {
            if (recipe.getPrimary().getItemId() != currentItem) continue;

            final RecipeRun run = new RecipeRun(recipe, held / recipe.getPrimary().getQuantity());
            runs.add(run);

            currentItem = recipe.getOutput().getItemId();
            held = run.getOutputQuantity();
        }

        return runs;
    }

    /**
     * @return how much of each secondary the given runs consume
     */
    static ItemQuantities sumSecondaryDemand(List<RecipeRun> runs) {
        final Map<Integer, Double> demanded = new HashMap<>();

        for (RecipeRun run : runs) {
            for (Ingredient secondary : run.getRecipe().getSecondaries()) {
                demanded.merge(secondary.getItemId(), run.getRuns() * secondary.getQuantity(), Double::sum);
            }
        }

        return ItemQuantities.of(demanded);
    }

    private static List<Integer> findOwnedItemsInChain(RecipeChain chain, ItemQuantities owned) {
        final List<Integer> onChain = new ArrayList<>();

        if (owned.get(chain.getRootItemId()) > 0) onChain.add(chain.getRootItemId());

        for (Recipe recipe : chain.getRecipes()) {
            final int output = recipe.getOutput().getItemId();
            if (owned.get(output) > 0) onChain.add(output);
        }

        return onChain;
    }

    private static double sumOutputQuantity(List<RecipeRun> runs, int product) {
        double quantity = 0;

        for (RecipeRun run : runs) {
            if (run.getRecipe().getOutput().getItemId() == product) quantity += run.getOutputQuantity();
        }

        return quantity;
    }
}

package adamski.domain.result;

import adamski.domain.Recipe;
import adamski.domain.RecipeTag;
import adamski.domain.route.RecipeChain;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.UnaryOperator;

public final class RecipeModifiers {
    private RecipeModifiers() {
    }

    /**
     * Rebuilds the chains with each recipe passed through the provided modifiers in list order.
     */
    public static List<RecipeChain> apply(List<RecipeChain> chains, List<UnaryOperator<Recipe>> modifiers) {
        final List<RecipeChain> applied = new ArrayList<>(chains.size());

        for (RecipeChain chain : chains) {
            final List<Recipe> recipes = new ArrayList<>(chain.getRecipes().size());

            for (Recipe recipe : chain.getRecipes()) {
                Recipe modified = recipe;
                for (UnaryOperator<Recipe> modifier : modifiers) {
                    modified = modifier.apply(modified);
                }
                recipes.add(modified);
            }

            applied.add(new RecipeChain(chain.getRootItemId(), recipes));
        }

        return applied;
    }

    /**
     * Replaces each recipe's output quantity.
     */
    public static UnaryOperator<Recipe> outputOverrides(Map<Integer, Double> outputByRecipeId) {
        return recipe -> {
            final Double output = outputByRecipeId.get(recipe.getId());
            return output == null ? recipe : recipe.withOutputQuantity(output);
        };
    }

    /**
     * Scales the specified recipe's ingredient's multiplicatively without affecting the output.
     * Scaling the primary changes the runs per banked item, and so the xp;
     * scaling a secondary only changes demand.
     *
     * @throws IllegalArgumentException when applied to a recipe that does not use a listed item
     */
    public static UnaryOperator<Recipe> inputScaling(Map<Integer, Set<Integer>> itemsByRecipeId, double factor) {
        return recipe -> {
            Recipe scaled = recipe;
            for (int itemId : itemsByRecipeId.getOrDefault(recipe.getId(), Set.of())) {
                scaled = scaled.withIngredientScaled(itemId, factor);
            }
            return scaled;
        };
    }

    /**
     * Scales the xp of every recipe with the given tag, leaving its ingredients and output alone.
     */
    public static UnaryOperator<Recipe> xpScaling(RecipeTag tag, double factor) {
        return recipe -> recipe.getTag() == tag ? recipe.withXp((float) (recipe.getXp() * factor)) : recipe;
    }

    /**
     * Scales each recipe's output multiplicatively without affecting inputs and secondaries.
     */
    public static UnaryOperator<Recipe> outputScaling(Map<Integer, Double> factorByRecipeId) {
        return recipe -> {
            final Double factor = factorByRecipeId.get(recipe.getId());
            return factor == null ? recipe : recipe.withOutputQuantity(recipe.getOutput().getQuantity() * factor);
        };
    }
}

