package adamski.domain.route;

import adamski.domain.Recipe;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

import java.util.List;

/**
 * A chain of recipes to turn one banked item into one product.
 * <p>
 * Everything banked along the chain joins it rather than starting its own, which is why
 * holding ranarr seeds, grimy ranarr and ranarr unf gives one chain and not three.
 */
@Getter
@EqualsAndHashCode
@ToString
public final class RecipeChain {
    private final int rootItemId;

    private final int productItemId;

    private final List<Recipe> recipes;

    /**
     * A chain starting at the first recipe's primary, so it needs at least one recipe.
     */
    public RecipeChain(List<Recipe> recipes) {
        this(firstPrimaryOf(recipes), recipes);
    }

    /**
     * @param rootItemId the banked item the chain starts from
     * @param recipes    the route it takes, in order. Empty when the root itself has been told to
     *                   stop, which makes the root its own product - the chain still exists so the
     *                   choice that stopped it can be changed.
     */
    public RecipeChain(int rootItemId, List<Recipe> recipes) {
        validateIsOrdered(rootItemId, recipes);

        this.rootItemId = rootItemId;
        this.recipes = List.copyOf(recipes);
        this.productItemId = this.recipes.isEmpty()
                ? rootItemId
                : this.recipes.get(this.recipes.size() - 1).getOutput().getItemId();    }

    private static int firstPrimaryOf(List<Recipe> recipes) {
        if (recipes.isEmpty()) throw new IllegalArgumentException("a chain without recipes needs its root named");

        return recipes.get(0).getPrimary().getItemId();
    }

    private static void validateIsOrdered(int rootItemId, List<Recipe> recipes) {
        int holding = rootItemId;

        for (Recipe recipe : recipes) {
            if (recipe.getPrimary().getItemId() != holding) {
                throw new IllegalArgumentException("r" + recipe.getId() + " takes item "
                        + recipe.getPrimary().getItemId() + ", but the chain is holding item " + holding);
            }

            holding = recipe.getOutput().getItemId();
        }
    }
}

package adamski.domain.route;


import adamski.domain.ItemQuantities;
import adamski.domain.Recipe;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Works out which chains are produced from owned items.
 * <p>
 * The least mature banked item roots a chain and everything on its chosen route joins that chain.
 * Anything off that route roots a chain of its own - off the route, not unable to reach the product.
 * Banked torstol unf roots its own chain when torstol goes straight to super combat, though it makes
 * super combat too; it simply is not on the way.
 * <p>
 * A banked item told to stop still roots a chain, one with no recipes that makes nothing. Its row is
 * the only place left to change that choice once the items above it are used up.
 */
public final class RecipeChainResolver {
    private final RecipeGraph graph;

    public RecipeChainResolver(RecipeGraph graph) {
        this.graph = graph;
    }

    /**
     * @param owned     what the player holds
     * @param selection which recipe each item feeds
     * @return the chains, least mature root first. The panel relies on this to order rows of one
     * family - seed before grimy before unf.
     */
    public List<RecipeChain> resolve(ItemQuantities owned, RecipeSelection selection) {
        final List<Integer> banked = new ArrayList<>(owned.itemIds());

        // Banked items sorted by recipe dependency order (i.e. maturity)
        // This ordering ensures that chains begin with their root i.e. seed rather than herb
        banked.sort(Comparator.comparingInt(graph::maturityOf));

        final Set<Integer> claimed = new HashSet<>();
        final List<RecipeChain> chains = new ArrayList<>();

        for (Integer itemId : banked) {
            if (claimed.contains(itemId)) continue;

            // an item that can make nothing is no chain, but one that was told to stop still is
            if (graph.recipeOptionsFor(itemId).isEmpty()) continue;

            final List<Recipe> route = graph.findRoute(itemId, selection);
            chains.add(new RecipeChain(itemId, route));

            claimed.add(itemId);
            for (Recipe recipe : route) {
                claimed.add(recipe.getOutput().getItemId());
            }
        }

        return Collections.unmodifiableList(chains);
    }
}

package adamski.domain.route;


import adamski.domain.Recipe;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Recipe table as a graph, with a recipe being one edge from its primary to its output.
 * Secondaries are not part of the graph.
 */
public final class RecipeGraph {
    private final Map<Integer, List<Recipe>> options = new LinkedHashMap<>();
    private final Map<Integer, Integer> maturity = new HashMap<>();

    public RecipeGraph(List<Recipe> recipes) {
        final Set<Integer> items = new LinkedHashSet<>();

        for (Recipe recipe : recipes) {
            options.computeIfAbsent(recipe.getPrimary().getItemId(), k -> new ArrayList<>()).add(recipe);

            items.add(recipe.getPrimary().getItemId());
            items.add(recipe.getOutput().getItemId());
        }

        final List<Integer> sorted = sortByDependency(items);
        for (int i = 0; i < sorted.size(); i++) {
            maturity.put(sorted.get(i), i);
        }
    }

    /**
     * @return what this item can be turned into in one step, in table order
     */
    public List<Recipe> recipeOptionsFor(int itemId) {
        return Collections.unmodifiableList(options.getOrDefault(itemId, Collections.emptyList()));
    }

    /**
     * Everything this item can eventually become, which is what the product picker offers. Intermediates
     * are included - stopping at an unfinished potion is a valid choice.
     */
    public Set<Integer> findItemsReachableFrom(int itemId) {
        final Set<Integer> reached = new LinkedHashSet<>();
        final Deque<Integer> pending = new ArrayDeque<>();
        pending.add(itemId);

        while (!pending.isEmpty()) {
            for (Recipe recipe : recipeOptionsFor(pending.poll())) {
                final int output = recipe.getOutput().getItemId();
                if (reached.add(output)) pending.add(output);
            }
        }

        return Collections.unmodifiableSet(reached);
    }

    /**
     * @return the recipes that produce the potential final products for each item.
     */
    public Map<Integer, List<Recipe>> findProductRecipesByItem() {
        final Map<Integer, List<Recipe>> byItem = new HashMap<>();

        for (int itemId : options.keySet()) {
            final List<Recipe> productRecipes = new ArrayList<>();

            for (int productItemId : findItemsReachableFrom(itemId)) {
                final List<Recipe> route = findShortestRoute(itemId, productItemId);
                productRecipes.add(route.get(route.size() - 1));
            }

            byItem.put(itemId, List.copyOf(productRecipes));
        }

        return Collections.unmodifiableMap(byItem);
    }

    /**
     * The recipes turning one item into another, by the fewest steps. Where several routes reach the
     * product - torstol makes super combat directly or by way of the unf vial - the shortest is the
     * one a picked product means. The others are worth the same xp, which
     * {@code HerbloreRecipesTest.everyRouteToAProductIsWorthTheSameXp} holds the table to, so
     * nothing is lost by not offering them.
     *
     * @return the recipes to apply in order, empty if the product cannot be reached
     */
    public List<Recipe> findShortestRoute(int from, int product) {
        final Map<Integer, Recipe> arrivedBy = new HashMap<>();
        final Deque<Integer> pending = new ArrayDeque<>();
        pending.add(from);

        while (!pending.isEmpty()) {
            for (Recipe recipe : recipeOptionsFor(pending.poll())) {
                final int output = recipe.getOutput().getItemId();
                if (output == from || arrivedBy.containsKey(output)) continue;

                arrivedBy.put(output, recipe);
                if (output == product) return retrace(arrivedBy, from, product);

                pending.add(output);
            }
        }

        return Collections.emptyList();
    }

    /**
     * The route an item takes under a selection, one step at a time until an item is set to
     * {@link RecipeSelection#STOP} or feeds nothing.
     * <p>
     * A step naming a recipe this item no longer offers is stale config, and falls back to the
     * default rather than ending the chain - a chain must never vanish because the table moved
     * under a saved choice.
     *
     * @return the recipes to apply in order, empty if this item makes nothing
     */
    public List<Recipe> findRoute(int itemId, RecipeSelection selection) {
        final List<Recipe> route = new ArrayList<>();
        final Set<Integer> walked = new HashSet<>();

        int item = itemId;
        while (walked.add(item)) {
            final Recipe next = findNextStep(item, selection);
            if (next == null) break;

            route.add(next);
            item = next.getOutput().getItemId();
        }

        return Collections.unmodifiableList(route);
    }

    private Recipe findNextStep(int itemId, RecipeSelection selection) {
        final List<Recipe> options = recipeOptionsFor(itemId);
        if (options.isEmpty()) return null;

        final int chosen = selection.recipeIdFor(itemId);
        if (chosen == RecipeSelection.STOP) return null;

        for (Recipe option : options) {
            if (option.getId() == chosen) return option;
        }

        return options.get(0);
    }

    /**
     * How far along a chain an item sits. Lower comes first, and an item always ranks below anything
     * its production depends on, so sorting by this never puts a consumer before its producer.
     */
    public int maturityOf(int itemId) {
        return maturity.getOrDefault(itemId, Integer.MAX_VALUE);
    }

    private static List<Recipe> retrace(Map<Integer, Recipe> arrivedBy, int from, int product) {
        final List<Recipe> route = new ArrayList<>();

        int item = product;
        while (item != from) {
            final Recipe recipe = arrivedBy.get(item);
            route.add(recipe);
            item = recipe.getPrimary().getItemId();
        }

        Collections.reverse(route);

        return Collections.unmodifiableList(route);
    }

    /**
     * Kahn's algorithm to put every item after everything that makes it e.g. seed -> herb -> potion.
     *
     * @throws IllegalStateException if the table has a cycle, to catch data issues
     */
    private List<Integer> sortByDependency(Set<Integer> items) {
        final Map<Integer, Integer> remaining = new HashMap<>();
        for (Integer item : items) {
            for (Recipe recipe : recipeOptionsFor(item)) {
                remaining.merge(recipe.getOutput().getItemId(), 1, Integer::sum);
            }
        }

        final Deque<Integer> ready = new ArrayDeque<>();
        final List<Integer> sorted = new ArrayList<>(items.size());

        for (Integer item : items) {
            if (remaining.getOrDefault(item, 0) == 0) ready.add(item);
        }

        while (!ready.isEmpty()) {
            final Integer item = ready.poll();
            sorted.add(item);

            for (Recipe recipe : recipeOptionsFor(item)) {
                final int output = recipe.getOutput().getItemId();
                if (remaining.merge(output, -1, Integer::sum) == 0) ready.add(output);
            }
        }

        if (sorted.size() != items.size()) {
            final Set<Integer> cyclic = new LinkedHashSet<>(items);
            sorted.forEach(cyclic::remove);
            throw new IllegalStateException("recipe table has a dependency cycle among items: " + cyclic);
        }

        return sorted;
    }
}

package adamski.domain.route;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/**
 * For each item, the recipe it goes into. {@link #STOP} designates to go
   no further. An item with no entry takes the first recipe the table offers.
 * <p>
 * The product is found by following the steps until one says {@link
   #STOP} or the item feeds nothing.
 */
public final class RecipeSelection {
    public static final int DEFAULT = 0;
    public static final int STOP = -1;

    public static final RecipeSelection ALL_DEFAULT = new RecipeSelection(Collections.emptyMap());

    private final Map<Integer, Integer> recipeByItemId;

    private RecipeSelection(Map<Integer, Integer> recipeByItemId) {
        this.recipeByItemId = recipeByItemId;
    }

    /**
     * @param recipeByItemId item to the recipe it feeds, {@link #STOP}, or {@link #DEFAULT}. A
     *                       {@link #DEFAULT} entry is dropped, the same as leaving the item out, so
     *                       two selections that mean the same thing are equal.
     */
    public static RecipeSelection of(Map<Integer, Integer> recipeByItemId) {
        final Map<Integer, Integer> chosen = new HashMap<>(recipeByItemId);
        chosen.values().removeIf(recipeId -> recipeId == DEFAULT);

        return chosen.isEmpty() ? ALL_DEFAULT : new RecipeSelection(chosen);
    }

    /**
     * @param recipeByItemId entries to lay over the current selection: an item to the recipe it feeds,
     *                       {@link #STOP}, or {@link #DEFAULT} to drop the item back to its default
     * @return a new selection with those entries applied
     */
    public RecipeSelection with(Map<Integer, Integer> recipeByItemId) {
        final Map<Integer, Integer> merged = new HashMap<>(this.recipeByItemId);
        merged.putAll(recipeByItemId);

        return of(merged);
    }

    /**
     * @return the recipe id this item feeds, {@link #STOP}, or {@link #DEFAULT} to take the first
     * option the table offers
     */
    public int recipeIdFor(int itemId) {
        return recipeByItemId.getOrDefault(itemId, DEFAULT);
    }

    /**
     * @return every item with a choice, to the recipe it feeds or {@link #STOP} - never
     * {@link #DEFAULT}, which is the same as no entry. {@link #of} takes it back unchanged, so this
     * is what to save.
     */
    public Map<Integer, Integer> recipeByItemId() {
        return Collections.unmodifiableMap(recipeByItemId);
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) return true;
        if (!(other instanceof RecipeSelection)) return false;

        return recipeByItemId.equals(((RecipeSelection) other).recipeByItemId);
    }

    @Override
    public int hashCode() {
        return Objects.hashCode(recipeByItemId);
    }

    @Override
    public String toString() {
        return "RecipeSelection" + recipeByItemId;
    }
}

package adamski.domain.route;

import adamski.domain.Recipe;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Given a final product for a chain's root item, updates the intermediate steps inside the {@link RecipeSelection}.
 */
public final class RecipeSelector {
    private final RecipeGraph graph;

    public RecipeSelector(RecipeGraph graph) {
        this.graph = graph;
    }

    /**
     * Points a chain at a product, replacing the chain's previously assigned steps.
     *
     * @param current       what is stored now
     * @param rootItemId    the item the chain starts from
     * @param productItemId what it should end at, {@code rootItemId} itself to make nothing, or
     *                      {@link RecipeSelection#DEFAULT} for its default
     * @return the selection to store, or {@code current} unchanged if the product cannot be reached
     */
    public RecipeSelection select(RecipeSelection current, int rootItemId, int productItemId) {
        // clear the current route first, root included - a root told to stop has no route to clear
        final Map<Integer, Integer> recipeByItemId = new LinkedHashMap<>();
        recipeByItemId.put(rootItemId, RecipeSelection.DEFAULT);
        for (Recipe recipe : graph.findRoute(rootItemId, current)) {
            recipeByItemId.put(recipe.getPrimary().getItemId(), RecipeSelection.DEFAULT);
            recipeByItemId.put(recipe.getOutput().getItemId(), RecipeSelection.DEFAULT);
        }

        if (productItemId == RecipeSelection.DEFAULT) return current.with(recipeByItemId);

        // ending where it starts takes no route at all - the row makes nothing
        final List<Recipe> route = graph.findShortestRoute(rootItemId, productItemId);
        if (route.isEmpty() && productItemId != rootItemId) return current;

        for (Recipe recipe : route) {
            recipeByItemId.put(recipe.getPrimary().getItemId(), recipe.getId());
        }

        // ensure the chain ends at the product
        if (!graph.recipeOptionsFor(productItemId).isEmpty()) {
            recipeByItemId.put(productItemId, RecipeSelection.STOP);
        }

        return current.with(recipeByItemId);
    }
}

package adamski.infrastructure;

import adamski.data.Recipes;
import adamski.data.PotionDoses;
import adamski.domain.ItemQuantities;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;

/**
 * Tracks the bank's Potion Storage.
 */
@Singleton
public class PotionStorageAdapter {
    /**
      Unlike the item containers, the RuneLite API doesn't expose a change event. This class handles that by listening
     to when the bank interface finishes rebuilding or when varps indicating a potion storage interface rebuild arrive,
     then reading the potion storage.
     */

    private final Client client;

    private boolean dirty;

    private Set<Integer> varps;

    @Inject
    public PotionStorageAdapter(Client client) {
        this.client = client;
    }

    public void scriptFired(int scriptId) {
        // The bank interface rebuilding is the non-varp way the store can change.
        if (scriptId == ScriptID.BANKMAIN_FINISHBUILDING) {
            dirty = true;

            if (varps == null) {
                initialiseVarps();
            }
        }
    }

    public void varbitChanged(int varpId) {
        if (varps != null && varps.contains(varpId)) {
            dirty = true;
        }
    }

    /**
     * @return a map of potion doses (by canonical, single-dose item ID) if a change occurred; otherwise null
     */
    public ItemQuantities poll() {
        if (!dirty) return null;
        dirty = false;
        return ItemQuantities.counted(getPotions());
    }

    private void initialiseVarps() {
        final Widget widget = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
        if (widget == null) return;

        final int[] triggers = widget.getVarTransmitTrigger();
        if (triggers == null || triggers.length == 0) return;

        varps = new HashSet<>();
        Arrays.stream(triggers).forEach(varps::add);
    }

    private Map<Integer, Integer> getPotions() {
        final Map<Integer, Integer> doses = new HashMap<>();

        for (int groupEnumId : new int[]{EnumID.POTIONSTORE_POTIONS, EnumID.POTIONSTORE_UNFINISHED_POTIONS}) {
            final EnumComposition group = client.getEnum(groupEnumId);
            if (group == null) continue;

            for (int potionEnumId : group.getIntVals()) {
                final EnumComposition potion = client.getEnum(potionEnumId);
                if (potion == null) continue;

                // Read potion storage for current potion
                client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
                final int stored = client.getIntStack()[0];
                if (stored <= 0) continue;

                // Quantities are already 1 dose, but ItemId may need to be normalised
                final int canonicalId = PotionDoses.canonicalId(potion.getIntValue(1));

                // Filter for domain-relevant item IDs
                if (!Recipes.isRelevantItem(canonicalId)) continue;

                doses.merge(canonicalId, stored, Integer::sum);
            }
        }

        return doses;
    }
}

package adamski.infrastructure;

import adamski.app.HerbloreApp;
import adamski.data.Recipes;
import adamski.data.PotionDoses;
import adamski.data.SecondaryPrecursors;
import adamski.domain.ItemQuantities;
import adamski.domain.ItemSource;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;

/**
 * Adapts RuneLite events into domain language.
 */
@Singleton
public class RuneLiteAdapter {
    private final Client client;
    private final ItemManager itemManager;
    private final PotionStorageAdapter potionStorage;
    private final HerbloreApp app;

    private final Map<ItemSource, ItemQuantities> pending = new EnumMap<>(ItemSource.class);

    private final Map<Integer, ItemSource> inventoryItemSources = Map.of(
            InventoryID.BANK, ItemSource.Bank,
            InventoryID.SEED_VAULT, ItemSource.SeedVault
    );

    @Inject
    public RuneLiteAdapter(Client client, ItemManager itemManager, PotionStorageAdapter potionStorage,
                           HerbloreApp app) {
        this.client = client;
        this.itemManager = itemManager;
        this.potionStorage = potionStorage;
        this.app = app;
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        final var itemSource = inventoryItemSources.get(event.getContainerId());
        if (itemSource == null) return;

        pending.put(itemSource, getItemQuantitiesFromContainer(event.getItemContainer()));
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        if (event.getSkill() != Skill.HERBLORE) return;

        app.updateCurrentXp(event.getXp());
    }

    public void readCurrentXp() {
        if (client.getGameState() != GameState.LOGGED_IN) return;

        app.updateCurrentXp(client.getSkillExperience(Skill.HERBLORE));
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        potionStorage.scriptFired(event.getScriptId());
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        potionStorage.varbitChanged(event.getVarpId());
    }

    @Subscribe
    public void onClientTick(ClientTick event) {
        // Sources are gathered into an array and dispatched together so that simultaneous actions (e.g. deposit
        // inv to bank) dispatch one action rather than multiple.

        final var potionDoses = potionStorage.poll();
        if (potionDoses != null) {
            pending.put(ItemSource.PotionStorage, potionDoses);
        }

        if (pending.isEmpty()) return;

        app.updateItems(new EnumMap<>(pending));
        pending.clear();
    }

    private ItemQuantities getItemQuantitiesFromContainer(ItemContainer container) {
        if (container == null) return ItemQuantities.EMPTY;

        final Map<Integer, Integer> items = new HashMap<>();

        for (Item item : container.getItems()) {
            final var id = item.getId();

            if (id == -1 || item.getQuantity() <= 0) continue;

            // Filter placeholder items
            final var comp = itemManager.getItemComposition(id);
            if (comp.getPlaceholderTemplateId() != -1) continue;

            final var unnotedId = itemManager.canonicalize(id); // Merge noted items into unnoted form
            final var doses = item.getQuantity() * PotionDoses.doses(unnotedId);
            final var canonicalId = PotionDoses.canonicalId(unnotedId); // Reduce dose variants to 1-dose units
            if (!Recipes.isRelevantItem(canonicalId) && !SecondaryPrecursors.isPrecursor(canonicalId)) continue; // Filter for domain-relevant items

            items.merge(canonicalId, doses, Integer::sum);
        }

        return ItemQuantities.counted(items);
    }
}

package adamski.infrastructure;

import adamski.app.AlchemistAmuletListener;
import adamski.app.HerbloreApp;
import adamski.app.SelectionListener;
import adamski.domain.route.RecipeSelection;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;

/**
 * Persists the user's panel configuration.
 * Saves on every change; loads on login, on switching account, and when the plugin starts.
 */
@Slf4j
@Singleton
public class SelectionPersistence implements SelectionListener, AlchemistAmuletListener {
    static final String CONFIG_GROUP = "iron-herblore";
    static final String SELECTION_KEY = "selection";
    static final String AMULET_KEY = "amulet";

    private static final Type INTEGER_BY_INTEGER = new TypeToken<Map<Integer, Integer>>() {
    }.getType();

    private final ConfigManager configManager;
    private final ClientThread clientThread;
    private final Gson gson;
    private final HerbloreApp app;

    @Inject
    public SelectionPersistence(ConfigManager configManager, ClientThread clientThread, Gson gson, HerbloreApp app) {
        this.configManager = configManager;
        this.clientThread = clientThread;
        this.gson = gson;
        this.app = app;
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event) {
        // the app is only driven from the client thread; invoke runs at once if already there
        clientThread.invoke(this::load);
    }

    /**
     * Restores the current account's saved choices, or the defaults if it has none. Client thread
     * only.
     */
    public void load() {
        app.restoreSelection(decodeStoredRecipeSelection(configManager.getRSProfileConfiguration(CONFIG_GROUP, SELECTION_KEY)));
        app.restoreAmuletDoses(decodeStoredAmuletConfiguration(configManager.getRSProfileConfiguration(CONFIG_GROUP, AMULET_KEY)));
    }

    @Override
    public void onAmuletConfigurationChanged(Map<Integer, Integer> dosesPerPotionByRecipeId) {
        if (dosesPerPotionByRecipeId.isEmpty()) {
            configManager.unsetRSProfileConfiguration(CONFIG_GROUP, AMULET_KEY);
        } else {
            configManager.setRSProfileConfiguration(CONFIG_GROUP, AMULET_KEY, encodeAmulet(dosesPerPotionByRecipeId));
        }
    }

    String encodeAmulet(Map<Integer, Integer> dosesPerPotionByRecipeId) {
        return gson.toJson(dosesPerPotionByRecipeId, INTEGER_BY_INTEGER);
    }

    Map<Integer, Integer> decodeStoredAmuletConfiguration(String saved) {
        if (saved == null || saved.isEmpty()) return Map.of();

        try {
            final Map<Integer, Integer> dosesPerPotionByRecipeId = gson.fromJson(saved, INTEGER_BY_INTEGER);
            if (dosesPerPotionByRecipeId == null) return Map.of();

            final Map<Integer, Integer> readable = new HashMap<>(dosesPerPotionByRecipeId);
            readable.values().removeIf(doses -> doses == null);

            return readable;
        } catch (JsonParseException e) {
            log.warn("ignoring unreadable saved amulet choices: {}", saved, e);
            return Map.of();
        }
    }

    @Override
    public void onRecipeSelectionChanged(RecipeSelection selection) {
        if (selection.recipeByItemId().isEmpty()) {
            configManager.unsetRSProfileConfiguration(CONFIG_GROUP, SELECTION_KEY);
        } else {
            configManager.setRSProfileConfiguration(CONFIG_GROUP, SELECTION_KEY, encode(selection));
        }
    }

    String encode(RecipeSelection selection) {
        return gson.toJson(selection.recipeByItemId(), INTEGER_BY_INTEGER);
    }

    RecipeSelection decodeStoredRecipeSelection(String saved) {
        if (saved == null || saved.isEmpty()) return RecipeSelection.ALL_DEFAULT;

        try {
            final Map<Integer, Integer> recipeByItemId = gson.fromJson(saved, INTEGER_BY_INTEGER);
            if (recipeByItemId == null) return RecipeSelection.ALL_DEFAULT;

            final Map<Integer, Integer> readable = new HashMap<>(recipeByItemId);
            readable.values().removeIf(recipeId -> recipeId == null);

            return RecipeSelection.of(readable);
        } catch (JsonParseException e) {
            log.warn("ignoring an unreadable saved selection: {}", saved, e);
            return RecipeSelection.ALL_DEFAULT;
        }
    }
}

package adamski.ui;

public final class Amounts {
    private Amounts() {
    }

    /**
     * Short enough to sit beside an item name in a panel about 225px wide.
     */
    public static String abbreviate(double value) {
        final String sign = value < 0 ? "-" : "";
        final double magnitude = Math.abs(value);

        if (magnitude >= 1_000_000) return sign + String.format("%.1fm", magnitude / 1_000_000);
        if (magnitude >= 10_000) return sign + String.format("%.0fk", magnitude / 1_000);
        if (magnitude >= 1_000) return sign + String.format("%.1fk", magnitude / 1_000);

        return sign + String.format("%.0f", magnitude);
    }

    /**
     * As {@link #abbreviate}, but keeping one decimal from 1k up to 50k - "15.5k" rather than "16k" -
     * where a potion's dose count needs it.
     */
    public static String abbreviateDoses(double value) {
        final double magnitude = Math.abs(value);

        if (magnitude >= 1_000 && magnitude < 50_000) {
            return (value < 0 ? "-" : "") + String.format("%.1fk", magnitude / 1_000);
        }

        return abbreviate(value);
    }
}

package adamski.ui;

import adamski.data.AlchemistsAmulet;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

import javax.swing.ButtonGroup;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToggleButton;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.IntConsumer;

/**
 * One line per potion: its name, the sizes an upgrade can be made in, and a box to use the amulet on
 * it. Sizes run smallest first, so 3 sits by the box and lines up down the list. Ticking the box
 * picks 3. Rebuilt for every result.
 */
class AmuletPanel extends JPanel {
    // one 15% chance of a dose per potion, spread over its doses
    private static final Map<Integer, String> GAIN_BY_DOSES = Map.of(1, "+15%", 2, "+7.5%", 3, "+5%");

    private static final Dimension SIZE_BUTTON = new Dimension(22, 18);

    AmuletPanel(AmuletView amulet, BiConsumer<Integer, Integer> onSet, IntConsumer onClear) {
        setLayout(new DynamicGridLayout(0, 1, 0, 1));
        // on the panel's own grey, not a block like the secondaries': the theme's checkboxes are
        // drawn for that grey and all but vanish on the rows' shade
        setOpaque(false);

        for (AmuletView.Line line : amulet.getLines()) {
            add(lineOf(line, onSet, onClear));
        }
    }

    private static JPanel lineOf(AmuletView.Line line, BiConsumer<Integer, Integer> onSet, IntConsumer onClear) {
        final JCheckBox used = new JCheckBox((String) null, line.isUsed());
        used.setOpaque(false);
        used.setFocusPainted(false);
        used.setBorder(new EmptyBorder(0, 0, 0, 0));
        used.addActionListener(e -> {
            if (used.isSelected()) onSet.accept(line.getRecipeId(), AlchemistsAmulet.DEFAULT_DOSES_PER_POTION);
            else onClear.accept(line.getRecipeId());
        });

        // clicking the name ticks the box too
        final JLabel name = new JLabel(line.getName());
        name.setFont(FontManager.getRunescapeSmallFont());
        name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        name.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        name.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                used.doClick();
            }
        });

        final JPanel controls = new JPanel(new GridBagLayout());
        controls.setOpaque(false);
        final GridBagConstraints next = new GridBagConstraints();
        next.insets = new Insets(0, 0, 0, 6);
        if (line.getDosesPerPotionOptions().size() > 1) {
            controls.add(sizesOf(line, onSet), next);
        }
        next.insets = new Insets(0, 0, 0, 0);
        controls.add(used, next);

        final JPanel panel = new JPanel(new BorderLayout(6, 0));
        panel.setOpaque(false);
        panel.add(name, BorderLayout.CENTER);
        panel.add(controls, BorderLayout.EAST);

        return panel;
    }

    private static JPanel sizesOf(AmuletView.Line line, BiConsumer<Integer, Integer> onSet) {
        final List<Integer> smallestFirst = new ArrayList<>(line.getDosesPerPotionOptions());
        Collections.sort(smallestFirst);

        final JPanel buttons = new JPanel(new GridLayout(1, smallestFirst.size(), 0, 0));
        buttons.setOpaque(false);
        final ButtonGroup group = new ButtonGroup();

        for (int doses : smallestFirst) {
            final JToggleButton button = new JToggleButton(String.valueOf(doses),
                    Integer.valueOf(doses).equals(line.getDosesPerPotion()));
            button.setFont(FontManager.getRunescapeSmallFont());
            button.setMargin(new Insets(0, 0, 0, 0));
            button.setFocusPainted(false);
            button.setPreferredSize(SIZE_BUTTON);
            button.setToolTipText("Upgrade " + doses + "-dose potions: " + GAIN_BY_DOSES.get(doses) + " doses"
                    + (doses < AlchemistsAmulet.DEFAULT_DOSES_PER_POTION ? ", but more clicks" : ""));
            button.addActionListener(e -> onSet.accept(line.getRecipeId(), doses));

            group.add(button);
            buttons.add(button);
        }

        return buttons;
    }
}

package adamski.ui;

import lombok.Value;

import java.util.List;

/**
 * Only the choices: the extra doses show on the rows, and repeating them here would read as more.
 */
@Value
class AmuletView {
    double charges;

    List<Line> lines;

    @Value
    static class Line {
        int recipeId;

        String name;

        /**
         * More than one is an upgrade, offered as a choice.
         */
        List<Integer> dosesPerPotionOptions;

        /**
