}

package adamski.ui;

import adamski.app.HerbloreApp;
import adamski.app.ResultListener;
import adamski.domain.Recipe;
import adamski.app.HerbloreResult;
import adamski.ui.icon.CogIcon;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.stream.Collectors;

/**
 * Fields are touched on the EDT only, unless noted.
 */
public class HerblorePanel extends PluginPanel implements ResultListener {
    private static final int LOGO_SIZE = 20;

    // RuneLite's eye icons (Screen Markers, Loot Tracker; BSD-2), copied in and recoloured to match the cog
    private static final int EYE_SIZE = 14;
    private static final BufferedImage EYE_OPEN = ImageUtil.resizeImage(
            ImageUtil.loadImageResource(HerblorePanel.class, "eye_open.png"), EYE_SIZE, EYE_SIZE);
    private static final BufferedImage EYE_SHUT = ImageUtil.resizeImage(
            ImageUtil.loadImageResource(HerblorePanel.class, "eye_shut.png"), EYE_SIZE, EYE_SIZE);

    private static final Color BUTTON = new Color(0x8C, 0x8C, 0x8C);
    private static final Color BUTTON_HOVER = Color.WHITE;

    private final ItemManager itemManager;
    private final ClientThread clientThread;
    private final HerbloreApp app;
    private final RowViewFactory rowViewFactory;

    private final JLabel noData = new JLabel("Open your bank and/or seed vault");
    private final XpBar xpBar = new XpBar();
    private final JPanel rows = new JPanel(new DynamicGridLayout(0, 1, 0, 3));
    private final JPanel secondaries = new JPanel(new DynamicGridLayout(0, 1, 0, 1));
    private final JPanel amulet = new JPanel(new BorderLayout(0, 2));

    // What is open is kept here, because rows and sections are rebuilt for every result
    private final Set<Integer> expandedRootItemIds = new HashSet<>();
    private final Set<Integer> expandedSecondaryItemIds = new HashSet<>();
    private boolean amuletExpanded;
    private boolean recipesExpanded = true;
    private boolean secondariesExpanded = true;

    private final RowOrder rowOrder = new RowOrder();

    /**
     * A row whose view has not changed keeps its panel, so its hover and open menu survive.
     */
    private Map<Integer, RowView> shownRowByRootItemId = new HashMap<>();
    private Map<Integer, RowPanel> panelByRootItemId = new HashMap<>();

    /**
     * Kept here because ItemManager's cache holds only 128 across all plugins, and an evicted sprite
     * comes back blank for a moment, which flickers.
     */
    private final Map<Integer, AsyncBufferedImage> spriteByItemId = new HashMap<>();

    /**
     * Client thread. Set around selectProduct, which publishes before returning, so a result seen
     * while it is set is the one the pick produced.
     */
    private Integer pickingOnRootItemId;

    private boolean offRowsShown;
    private final Consumer<Boolean> offRowsShownSaver;

    /**
     * Every row including those switched off, so the eye can redraw without waiting for a result.
     */
    private List<Integer> arrangedRootItemIds = List.of();

    // built once, so its hover survives redraws
    private final JPanel recipesHeading;
    private final JLabel eye = new JLabel();

    private boolean active;

    /**
     * The latest result to arrive while the panel was closed. Skipping earlier ones loses nothing:
     * a closed panel cannot be picked on.
     */
    private Runnable pendingRender;

    /**
     * @param productRecipesByItem for each item, the recipe making each product it could end at -
     *                             what a row's menu offers
     */
    public HerblorePanel(ItemManager itemManager, ClientThread clientThread, HerbloreApp app,
                         Map<Integer, List<Recipe>> productRecipesByItem, BufferedImage icon,
                         Runnable openSettings, boolean offRowsShown, Consumer<Boolean> offRowsShownSaver) {
        this.itemManager = itemManager;
        this.clientThread = clientThread;
        this.app = app;
        this.offRowsShown = offRowsShown;
        this.offRowsShownSaver = offRowsShownSaver;
        this.rowViewFactory = new RowViewFactory(this::name, productRecipesByItem);

        setLayout(new BorderLayout());

        noData.setFont(FontManager.getRunescapeFont());
        noData.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        noData.setHorizontalAlignment(JLabel.CENTER);

        xpBar.setVisible(false);
        final JPanel header = new JPanel(new BorderLayout());
        header.setOpaque(false);
        header.setBorder(new EmptyBorder(0, 0, 8, 0));
        header.add(titleOf(icon, openSettings), BorderLayout.NORTH);
        header.add(noData, BorderLayout.CENTER);
        header.add(xpBar, BorderLayout.SOUTH);

        recipesHeading = recipesHeading();

        rows.setOpaque(false);
        amulet.setOpaque(false);
        amulet.setBorder(new EmptyBorder(10, 0, 0, 0));
        secondaries.setOpaque(false);
        secondaries.setBorder(new EmptyBorder(10, 0, 0, 0));

        final JPanel below = new JPanel(new BorderLayout());
        below.setOpaque(false);
        below.add(amulet, BorderLayout.NORTH);
        below.add(secondaries, BorderLayout.CENTER);

        final JPanel content = new JPanel(new BorderLayout());
        content.setOpaque(false);
        content.add(header, BorderLayout.NORTH);
        content.add(rows, BorderLayout.CENTER);
        content.add(below, BorderLayout.SOUTH);

        add(content, BorderLayout.NORTH);
    }

    private static JPanel titleOf(BufferedImage icon, Runnable openSettings) {
        final JLabel name = new JLabel("Iron Herblore", JLabel.CENTER);
        name.setFont(FontManager.getRunescapeBoldFont());
        name.setForeground(Color.WHITE);

        final JLabel logo = new JLabel(new ImageIcon(ImageUtil.resizeImage(icon, LOGO_SIZE, LOGO_SIZE, true)));

        final JLabel settings = new JLabel(new CogIcon(BUTTON));
        settings.setToolTipText("Settings");
        settings.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        settings.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                openSettings.run();
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                settings.setIcon(new CogIcon(BUTTON_HOVER));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                settings.setIcon(new CogIcon(BUTTON));
            }
        });

        // the icon and the cog take the same width, so the name centres on the panel
        final Dimension corner = new Dimension(LOGO_SIZE, LOGO_SIZE);
        logo.setPreferredSize(corner);
        settings.setPreferredSize(corner);

        final JPanel title = new JPanel(new BorderLayout());
        title.setOpaque(false);
        title.setBorder(new CompoundBorder(
                new CompoundBorder(new EmptyBorder(0, 0, 8, 0),
                        new MatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR)),
                new EmptyBorder(0, 0, 6, 0)));
        title.add(logo, BorderLayout.WEST);
        title.add(name, BorderLayout.CENTER);
        title.add(settings, BorderLayout.EAST);
        return title;
    }

    @Override
    public void onResultChanged(HerbloreResult result) {
        final XpBarView xpBarView = XpBarView.of(result.getCurrentXp(), result.getTotalXp());

        // Names resolve here, on the client thread - ItemManager cannot be touched from the EDT.
        // Rows worth nothing stay listed: a row stopped at an unf vial still needs its picker.
        final List<RowView> rowViews = result.getChainResults().stream()
                .map(chain -> rowViewFactory.rowOf(chain,
                        result.getAmuletChainRootItemIds().contains(chain.getRootItemId())))
                .collect(Collectors.toList());

        final List<SecondaryView> secondaryViews = rowViewFactory.secondariesOf(result.getSecondaryBalance());
        final AmuletView amuletView = rowViewFactory.amuletOf(result.getAmuletOptions(), result.getAmuletCharges());
        final Integer pickedOnRootItemId = pickingOnRootItemId;

        SwingUtilities.invokeLater(() -> {
            final Runnable render = () -> render(xpBarView, rowViews, pickedOnRootItemId, secondaryViews, amuletView);

            if (active) {
                render.run();
            } else {
                pendingRender = render;
            }
        });
    }

    @Override
    public void onActivate() {
        active = true;

        if (pendingRender != null) {
            pendingRender.run();
            pendingRender = null;
        }
    }

    @Override
    public void onDeactivate() {
        active = false;
    }

    private void render(XpBarView xpBarView, List<RowView> rowViews, Integer pickedOnRootItemId,
                        List<SecondaryView> secondaryViews, AmuletView amuletView) {
        noData.setVisible(false);
        xpBar.setVisible(true);
        xpBar.setView(xpBarView);

        final Map<Integer, RowView> rowByRootItemId = new HashMap<>();
        for (RowView row : rowViews) {
            rowByRootItemId.put(row.getRootItemId(), row);
        }

        arrangedRootItemIds = rowOrder.arrange(
                rowViews.stream().map(RowView::getRootItemId).collect(Collectors.toList()),
                pickedOnRootItemId);
        drawRows(rowByRootItemId);

        amulet.removeAll();
        if (!amuletView.getLines().isEmpty()) {
            final AmuletPanel choices = new AmuletPanel(amuletView, this::setAmuletDoses, this::clearAmuletDoses);
            choices.setVisible(amuletExpanded);
            amulet.add(amuletHeadingOf(amuletView, choices), BorderLayout.NORTH);
            amulet.add(choices, BorderLayout.CENTER);
        }

        secondaries.removeAll();
        if (!secondaryViews.isEmpty()) {
            final JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 1));
            list.setBackground(RowPanel.ROOT_SHADE);
            list.setBorder(new EmptyBorder(3, 0, 3, 0));
            list.setVisible(secondariesExpanded);

            secondaries.add(new SectionHeading("Secondaries", secondariesExpanded, expanded -> {
                secondariesExpanded = expanded;
                list.setVisible(expanded);
                secondaries.revalidate();
                secondaries.repaint();
            }, null, null));
            secondaries.add(list);

            for (SecondaryView secondary : secondaryViews) {
                final int itemId = secondary.getItemId();
                list.add(new SecondaryPanel(secondary, expandedSecondaryItemIds.contains(itemId),
                        expanded -> {
                            if (expanded) expandedSecondaryItemIds.add(itemId);
                            else expandedSecondaryItemIds.remove(itemId);
                        }));
            }
        }

        revalidate();
        repaint();
    }

    /**
     * The app is only driven from the client thread; the new result comes back through
     * onResultChanged.
     */
    private void selectProduct(int rootItemId, int productItemId) {
        clientThread.invoke(() -> {
            pickingOnRootItemId = rootItemId;
            try {
                app.selectProduct(rootItemId, productItemId);
            } finally {
                pickingOnRootItemId = null;
            }
        });
    }

    private void setAmuletDoses(int recipeId, int dosesPerPotion) {
        clientThread.invoke(() -> app.setAmuletDoses(recipeId, dosesPerPotion));
    }

    private void clearAmuletDoses(int recipeId) {
        clientThread.invoke(() -> app.clearAmuletDoses(recipeId));
    }

    private JPanel amuletHeadingOf(AmuletView amuletView, AmuletPanel choices) {
        final JLabel charges = new JLabel(Math.round(amuletView.getCharges()) == 0
                ? ""
                : Amounts.abbreviate(Math.ceil(amuletView.getCharges())) + " charges");
        charges.setFont(FontManager.getRunescapeSmallFont());
        charges.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        charges.setToolTipText("One charge per extra dose the amulet makes, on average");

        return new SectionHeading("Alchemist's amulet", amuletExpanded, expanded -> {
            amuletExpanded = expanded;
            choices.setVisible(expanded);
            amulet.revalidate();
            amulet.repaint();
        }, charges, null);
    }

    private void drawRows(Map<Integer, RowView> rowByRootItemId) {
        final Map<Integer, RowPanel> panels = new HashMap<>();
        rows.removeAll();
        if (!arrangedRootItemIds.isEmpty()) {
            rows.add(recipesHeading);
        }

        for (int rootItemId : arrangedRootItemIds) {
            final RowView row = rowByRootItemId.get(rootItemId);
            if (!offRowsShown && row.isSwitchedOff()) continue;

            RowPanel panel = panelByRootItemId.get(rootItemId);
            if (panel == null || !row.equals(shownRowByRootItemId.get(rootItemId))) {
                panel = new RowPanel(row, expandedRootItemIds.contains(rootItemId),
                        expanded -> {
                            if (expanded) expandedRootItemIds.add(rootItemId);
                            else expandedRootItemIds.remove(rootItemId);
                        },
                        this::selectProduct,
                        this::spriteOf);
            }

            panels.put(rootItemId, panel);
            // kept even while folded, so opening the section rebuilds nothing
            if (recipesExpanded) rows.add(panel);
        }

        shownRowByRootItemId = rowByRootItemId;
        panelByRootItemId = panels;
    }

    private JPanel recipesHeading() {
        updateEye(false);
        eye.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        eye.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                offRowsShown = !offRowsShown;
                offRowsShownSaver.accept(offRowsShown);
                updateEye(true);
                drawRows(shownRowByRootItemId);
                revalidate();
                repaint();
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                updateEye(true);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                updateEye(false);
            }
        });

        return new SectionHeading("Recipes", recipesExpanded, expanded -> {
            recipesExpanded = expanded;
            drawRows(shownRowByRootItemId);
            revalidate();
            repaint();
        }, null, eye);
    }

    private void updateEye(boolean hovered) {
        final BufferedImage image = offRowsShown ? EYE_OPEN : EYE_SHUT;
        eye.setIcon(new ImageIcon(tint(image, hovered ? BUTTON_HOVER : BUTTON)));
        eye.setToolTipText(offRowsShown ? "Hide rows switched off" : "Show rows switched off");
    }

    /**
     * Recolours while keeping each pixel's transparency. ImageUtil.fillImage makes every visible
     * pixel solid, which turns the eye, drawn in transparency, into a blob.
     */
    private static BufferedImage tint(BufferedImage image, Color color) {
        final BufferedImage tinted = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
        final int rgb = color.getRGB() & 0xFFFFFF;

        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                tinted.setRGB(x, y, (image.getRGB(x, y) & 0xFF000000) | rgb);
            }
        }

        return tinted;
    }

    private AsyncBufferedImage spriteOf(int itemId) {
        return spriteByItemId.computeIfAbsent(itemId, itemManager::getImage);
    }

    private String name(int itemId) {
        return itemManager.getItemComposition(itemId).getName();
    }
}

package adamski.ui;

import javax.swing.JComponent;
import javax.swing.JPopupMenu;
import javax.swing.event.PopupMenuEvent;
import javax.swing.event.PopupMenuListener;

import java.awt.AWTEvent;
import java.awt.EventQueue;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Opens a menu under its anchor on a press.
 * <p>
 * Swing closes an open menu on any press outside it before the press gets here, so a press on the
 * opener would close and reopen it at once. The press that just closed it is ignored.
 * <p>
 * The menu is built on the first press: most are never opened, and building one fetches a sprite
 * per option.
 */
final class MenuOpener extends MouseAdapter {
    private final Supplier<JPopupMenu> buildMenu;
    private final JComponent anchor;
    private final Consumer<Boolean> onHover;

    private JPopupMenu menu;

    private long closedByPressAt = -1;

    MenuOpener(Supplier<JPopupMenu> buildMenu, JComponent anchor, Consumer<Boolean> onHover) {
        this.buildMenu = buildMenu;
        this.anchor = anchor;
        this.onHover = onHover;
    }

    @Override
    public void mousePressed(MouseEvent e) {
        if (e.getWhen() == closedByPressAt) return;

        if (menu == null) menu = buildMenu();
        menu.show(anchor, 0, anchor.getHeight());
    }

    private JPopupMenu buildMenu() {
        final JPopupMenu built = buildMenu.get();
        built.addPopupMenuListener(new PopupMenuListener() {
            @Override
            public void popupMenuWillBecomeInvisible(PopupMenuEvent e) {
                final AWTEvent closedBy = EventQueue.getCurrentEvent();
                if (closedBy instanceof MouseEvent && closedBy.getID() == MouseEvent.MOUSE_PRESSED) {
                    closedByPressAt = ((MouseEvent) closedBy).getWhen();
                }
            }

            @Override
            public void popupMenuWillBecomeVisible(PopupMenuEvent e) {
            }

            @Override
            public void popupMenuCanceled(PopupMenuEvent e) {
            }
        });

        return built;
    }

    @Override
    public void mouseEntered(MouseEvent e) {
        onHover.accept(true);
    }

    @Override
    public void mouseExited(MouseEvent e) {
        onHover.accept(false);
    }
}

package adamski.ui;

import net.runelite.api.gameval.ItemID;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Which family a row belongs to, for ordering only: a row fed by ranarr seeds sits with the ranarr
 * rows. Herbs by level, then coral, then rows of no family, then caviar.
 */
final class RowFamilies {
    private static final Map<Integer, Integer> FAMILY_BY_ITEM_ID = new HashMap<>();

    private static final List<Integer> FAMILY_ORDER = new ArrayList<>();

    // stands in for every row of no family; not an item id
    private static final int THE_REST = -1;

    static {
        family(ItemID.GUAM_LEAF, ItemID.GUAM_SEED, ItemID.UNIDENTIFIED_GUAM, ItemID.GUAMVIAL);
        family(ItemID.MARENTILL, ItemID.MARRENTILL_SEED, ItemID.UNIDENTIFIED_MARENTILL, ItemID.MARRENTILLVIAL);
        family(ItemID.TARROMIN, ItemID.TARROMIN_SEED, ItemID.UNIDENTIFIED_TARROMIN, ItemID.TARROMINVIAL);
        family(ItemID.HARRALANDER, ItemID.HARRALANDER_SEED, ItemID.UNIDENTIFIED_HARRALANDER, ItemID.HARRALANDERVIAL);
        family(ItemID.RANARR_WEED, ItemID.RANARR_SEED, ItemID.UNIDENTIFIED_RANARR, ItemID.RANARRVIAL);
        family(ItemID.TOADFLAX, ItemID.TOADFLAX_SEED, ItemID.UNIDENTIFIED_TOADFLAX, ItemID.TOADFLAXVIAL);
        family(ItemID.IRIT_LEAF, ItemID.IRIT_SEED, ItemID.UNIDENTIFIED_IRIT, ItemID.IRITVIAL);
        family(ItemID.AVANTOE, ItemID.AVANTOE_SEED, ItemID.UNIDENTIFIED_AVANTOE, ItemID.AVANTOEVIAL);
        family(ItemID.KWUARM, ItemID.KWUARM_SEED, ItemID.UNIDENTIFIED_KWUARM, ItemID.KWUARMVIAL);
        family(ItemID.HUASCA, ItemID.HUASCA_SEED, ItemID.UNIDENTIFIED_HUASCA, ItemID.HUASCAVIAL);
        family(ItemID.SNAPDRAGON, ItemID.SNAPDRAGON_SEED, ItemID.UNIDENTIFIED_SNAPDRAGON, ItemID.SNAPDRAGONVIAL);
        family(ItemID.CADANTINE, ItemID.CADANTINE_SEED, ItemID.UNIDENTIFIED_CADANTINE, ItemID.CADANTINEVIAL);
        family(ItemID.LANTADYME, ItemID.LANTADYME_SEED, ItemID.UNIDENTIFIED_LANTADYME, ItemID.LANTADYMEVIAL);
        family(ItemID.DWARF_WEED, ItemID.DWARF_WEED_SEED, ItemID.UNIDENTIFIED_DWARF_WEED, ItemID.DWARFWEEDVIAL);
        family(ItemID.TORSTOL, ItemID.TORSTOL_SEED, ItemID.UNIDENTIFIED_TORSTOL, ItemID.TORSTOLVIAL);

        family(ItemID.CORAL_ELKHORN, ItemID.CORAL_ELKHORN_FRAG, ItemID.ELKHORNVIAL);
        family(ItemID.CORAL_PILLAR, ItemID.CORAL_PILLAR_FRAG, ItemID.PILLARVIAL);
        family(ItemID.CORAL_UMBRAL, ItemID.CORAL_UMBRAL_FRAG, ItemID.UMBRALVIAL);

        FAMILY_ORDER.add(THE_REST);

        family(ItemID.BRUT_CAVIAR, ItemID.BRUT_STURGEON);
    }

    private RowFamilies() {
    }

    private static int familyOf(int entryItemId) {
        return FAMILY_BY_ITEM_ID.getOrDefault(entryItemId, entryItemId);
    }

    /**
     * @return where this row's family is listed, lower first
     */
    static int familyRankOf(int entryItemId) {
        final int rank = FAMILY_ORDER.indexOf(familyOf(entryItemId));
        return rank < 0 ? FAMILY_ORDER.indexOf(THE_REST) : rank;
    }

    private static void family(int family, int... members) {
        FAMILY_ORDER.add(family);

        for (int member : members) {
            FAMILY_BY_ITEM_ID.put(member, family);
        }
    }
}

package adamski.ui;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Where each row sits, remembered between results so rows do not move about. Rows still there keep
 * their places. A row created by a pick goes straight after the row picked on; any other new row
 * goes to its family's place.
 */
final class RowOrder {
    private List<Integer> rootItemIds = new ArrayList<>();

    /**
     * @param incoming           every row's root, least mature first as the domain gives them, which
     *                           sets the order within a family
     * @param pickedOnRootItemId the row whose pick produced this result, or null
     */
    List<Integer> arrange(List<Integer> incoming, Integer pickedOnRootItemId) {
        final Map<Integer, Integer> incomingIndex = new HashMap<>();
        for (int i = 0; i < incoming.size(); i++) {
            incomingIndex.put(incoming.get(i), i);
        }

        final Comparator<Integer> familyOrder = Comparator
                .comparingInt(RowFamilies::familyRankOf)
                .thenComparingInt(incomingIndex::get);

        final List<Integer> arranged = new ArrayList<>(rootItemIds);
        arranged.retainAll(incomingIndex.keySet());

        final List<Integer> added = new ArrayList<>(incoming);
        added.removeAll(rootItemIds);

        if (pickedOnRootItemId != null && arranged.contains(pickedOnRootItemId)) {
            arranged.addAll(arranged.indexOf(pickedOnRootItemId) + 1, added);
        } else {
            for (int rootItemId : added) {
                arranged.add(placeFor(rootItemId, arranged, familyOrder), rootItemId);
            }
        }

        rootItemIds = arranged;

        return List.copyOf(arranged);
    }

    /**
     * Scans from the bottom rather than searching, because rows placed by a pick break family order,
     * and must not pull a new row up ahead of the families it really follows.
     */
    private static int placeFor(int rootItemId, List<Integer> arranged, Comparator<Integer> familyOrder) {
        for (int i = arranged.size() - 1; i >= 0; i--) {
            if (familyOrder.compare(arranged.get(i), rootItemId) < 0) return i + 1;
        }

        return 0;
    }
}

package adamski.ui;

import adamski.data.PotionDoses;
import adamski.ui.icon.CaretIcon;
import adamski.ui.icon.CornerArrowIcon;
import adamski.ui.icon.NoEntryIcon;
import adamski.ui.icon.RightArrowIcon;
import adamski.ui.icon.SmallSpriteIcon;
import adamski.ui.icon.StackIcon;
import net.runelite.api.gameval.ItemID;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;

import javax.swing.DefaultListCellRenderer;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.IntFunction;
import java.util.function.Supplier;

/**
 * One row, two lines tall:
 * <pre>
 *   [root]  Root item name           |        |
 *   [icon]  ↳ Product name      xp   | [prod] |
 * </pre>
 * The root's half folds the xp breakdown open; the product's half opens a menu of what else the row
 * could make. A row set to make nothing shrinks to one dim line, kept because it is the only place to
 * switch the row back on.
 * <p>
 * Immutable: a row whose view changes is replaced, not updated.
 */
class RowPanel extends JPanel {
    // also behind the secondaries section, so it reads as the same kind of thing as a row
    static final Color ROOT_SHADE = new Color(0x1d1d1d);
    static final Color ROOT_HOVER = new Color(0x262626);

    // behind a breakdown: darker than the line it folds out of, since lighter means hovered
    static final Color DETAIL_SHADE = new Color(0x181818);

    // the panel's own background, so a switched-off row all but disappears into it
    private static final Color OFF_SHADE = ColorScheme.DARK_GRAY_COLOR;
    private static final Color OFF_HOVER = ColorScheme.DARKER_GRAY_COLOR;
    private static final Color OFF_TEXT = Color.GRAY;

    private static final Dimension ROOT_ICON_CELL = new Dimension(40, 38);
    private static final Dimension PRODUCT_ICON_CELL = new Dimension(46, 38);

    private static final int MENU_MAX_HEIGHT = 240;

    private static final int MENU_OPTION_HEIGHT = 36;

    private static final Icon MAKE_NOTHING_ICON = new NoEntryIcon(ColorScheme.PROGRESS_ERROR_COLOR);

    /**
     * @param iconOf an item's plain sprite. Asked on the EDT, so ItemManager queues the drawing for
     *               the client thread rather than doing it there and then
     */
    RowPanel(RowView row, boolean expanded, Consumer<Boolean> onToggle,
                  BiConsumer<Integer, Integer> onProductSelected, IntFunction<AsyncBufferedImage> iconOf) {
        setLayout(new BorderLayout());
        setOpaque(false);

        final Supplier<JPopupMenu> menu = () -> buildMenu(row, onProductSelected, iconOf);

        if (row.isSwitchedOff()) {
            add(buildSwitchedOff(row, menu), BorderLayout.NORTH);
            return;
        }

        final JPanel detail = buildDetail(row);
        final boolean hasDetail = detail.getComponentCount() > 0;
        detail.setVisible(hasDetail && expanded);

        // the root's half
        final JLabel rootIcon = new JLabel();
        rootIcon.setHorizontalAlignment(SwingConstants.CENTER);
        rootIcon.setPreferredSize(ROOT_ICON_CELL);
        // no quantity on the root: it would count the root item alone, not everything on the row
        setIcon(rootIcon, new StackIcon(iconOf.apply(row.getRootItemId())));

        final JLabel rootName = new JLabel(row.getRootItemName());
        rootName.setFont(FontManager.getRunescapeBoldFont());
        rootName.setForeground(Color.WHITE);
        rootName.setBorder(new EmptyBorder(0, 2, 0, 6));
        rootName.setVerticalAlignment(SwingConstants.BOTTOM);

        // the product's half
        final JLabel arrow = new JLabel(new CornerArrowIcon(ColorScheme.BRAND_ORANGE));

        final JLabel xp = new JLabel(Amounts.abbreviate(row.getXp()));
        xp.setFont(FontManager.getRunescapeSmallFont());
        xp.setForeground(Color.WHITE);

        final JPanel notch = new JPanel(new BorderLayout(3, 0));
        notch.setBackground(ROOT_SHADE);
        notch.setBorder(new EmptyBorder(0, 3, 0, 6));
        notch.add(arrow, BorderLayout.WEST);
        notch.add(smallLabel(row.getProductName()), BorderLayout.CENTER);

        if (row.isAmuletUsed()) {
            // the amulet's extra doses are in the product's stack, so say where they came from
            final SmallSpriteIcon amulet = new SmallSpriteIcon(iconOf.apply(ItemID.AMULET_OF_CHEMISTRY_IMBUED_CHARGED));
            final JLabel marker = new JLabel(amulet);
            amulet.repaintWhenLoaded(marker);

            final JPanel east = new JPanel(new BorderLayout(3, 0));
            east.setOpaque(false);
            east.add(marker, BorderLayout.WEST);
            east.add(xp, BorderLayout.EAST);
            notch.add(east, BorderLayout.EAST);
        } else {
            notch.add(xp, BorderLayout.EAST);
        }

        final JLabel productIcon = new JLabel();
        productIcon.setHorizontalAlignment(SwingConstants.RIGHT);
        setStack(productIcon, iconOf.apply(row.getProductItemId()), row.getOutputQuantity(),
                PotionDoses.isPotion(row.getProductItemId()));

        final JLabel caret = new JLabel(new CaretIcon(ColorScheme.LIGHT_GRAY_COLOR));
        caret.setVerticalAlignment(SwingConstants.BOTTOM);
        caret.setBorder(new EmptyBorder(0, 0, 4, 3));

        final JPanel product = new JPanel(new BorderLayout());
        product.setBackground(ROOT_SHADE);
        product.setPreferredSize(PRODUCT_ICON_CELL);
        product.add(productIcon, BorderLayout.CENTER);
        product.add(caret, BorderLayout.EAST);

        final JPanel lines = new JPanel(new GridLayout(2, 1));
        lines.setOpaque(false);
        lines.add(rootName);
        lines.add(notch);

        final JPanel summary = new JPanel(new BorderLayout());
        summary.setBackground(ROOT_SHADE);
        summary.add(rootIcon, BorderLayout.WEST);
        summary.add(lines, BorderLayout.CENTER);
        summary.add(product, BorderLayout.EAST);

        detail.setBackground(DETAIL_SHADE);

        final String held = held(row);
        if (hasDetail) {
            final MouseAdapter toggle = new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    final boolean nowExpanded = !detail.isVisible();
                    detail.setVisible(nowExpanded);
                    onToggle.accept(nowExpanded);
                    revalidate();
                }

                @Override
                public void mouseEntered(MouseEvent e) {
                    summary.setBackground(ROOT_HOVER);
                }

                @Override
                public void mouseExited(MouseEvent e) {
                    summary.setBackground(ROOT_SHADE);
                }
            };
            listenOn(toggle, held + " - click for the xp breakdown", rootIcon, rootName);
        } else {
            rootIcon.setToolTipText(held);
            rootName.setToolTipText(held);
        }

        final String makes = "Makes " + Amounts.abbreviate(row.getOutputQuantity()) + " × " + row.getProductName()
                + (row.isAmuletUsed() ? ", with the alchemist's amulet" : "");
        listenOn(new MenuOpener(menu, summary, hovered -> {
            notch.setBackground(hovered ? ROOT_HOVER : ROOT_SHADE);
            product.setBackground(hovered ? ROOT_HOVER : ROOT_SHADE);
        }), makes + " - click to change", notch, product);

        add(summary, BorderLayout.NORTH);
        add(detail, BorderLayout.CENTER);
    }

    private static JPanel buildSwitchedOff(RowView row, Supplier<JPopupMenu> menu) {
        final JLabel name = smallLabel(row.getRootItemName());
        name.setForeground(OFF_TEXT);

        final JLabel off = smallLabel("off");
        off.setForeground(OFF_TEXT);
        off.setIcon(new CaretIcon(OFF_TEXT));
        off.setHorizontalTextPosition(SwingConstants.LEFT);
        off.setIconTextGap(4);

        final JPanel line = new JPanel(new BorderLayout(6, 0));
        line.setBackground(OFF_SHADE);
        line.setBorder(new CompoundBorder(
                new LineBorder(ColorScheme.DARKER_GRAY_COLOR),
                new EmptyBorder(3, 8, 3, 6)));
        line.add(name, BorderLayout.CENTER);
        line.add(off, BorderLayout.EAST);

        listenOn(new MenuOpener(menu, line, hovered -> line.setBackground(hovered ? OFF_HOVER : OFF_SHADE)),
                held(row) + " - makes nothing, click to choose a product", line);

        return line;
    }

    private static void setStack(JLabel label, AsyncBufferedImage sprite, double quantity, boolean doses) {
        setIcon(label, new StackIcon(sprite, quantity, doses));
    }

    private static void setIcon(JLabel label, StackIcon icon) {
        label.setIcon(icon);
        icon.repaintWhenLoaded(label);
    }

    private static String held(RowView row) {
        return Amounts.abbreviate(row.getRootQuantity()) + " × " + row.getRootItemName();
    }

    /**
     * Their child labels have no listeners of their own, so clicks on them reach these.
     */
    private static void listenOn(MouseAdapter listener, String toolTip, JComponent... components) {
        for (JComponent component : components) {
            component.addMouseListener(listener);
            component.setToolTipText(toolTip);
            component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        }
    }

    /**
     * A scrolling list in a popup, since a plain popup menu grows to fit, and caviar alone has enough
     * options to cover the panel.
     */
    private static JPopupMenu buildMenu(RowView row, BiConsumer<Integer, Integer> onProductSelected,
                                        IntFunction<AsyncBufferedImage> iconOf) {
        final List<RowView.ProductOption> options = row.getProductOptions();
        final JList<RowView.ProductOption> list = new JList<>(options.toArray(new RowView.ProductOption[0]));

        final List<Icon> icons = new ArrayList<>(options.size());
        for (RowView.ProductOption option : options) {
            if (option.getItemId() == row.getRootItemId()) {
                icons.add(MAKE_NOTHING_ICON);
                continue;
            }

            final AsyncBufferedImage image = iconOf.apply(option.getItemId());
            image.onLoaded(list::repaint);
            icons.add(new ImageIcon(image));
        }

        list.setFixedCellHeight(MENU_OPTION_HEIGHT);
        list.setCellRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> l, Object value, int index,
                                                          boolean isSelected, boolean cellHasFocus) {
                super.getListCellRendererComponent(l, value, index, isSelected, false);
                final RowView.ProductOption option = (RowView.ProductOption) value;
                setText(option.getName());
                setIcon(icons.get(index));
                setBorder(new EmptyBorder(2, 4, 2, 8));
                if (option.getItemId() == row.getProductItemId()) setFont(getFont().deriveFont(Font.BOLD));
                return this;
            }
        });

        final JScrollPane scroll = new JScrollPane(list) {
            @Override
            public Dimension getPreferredSize() {
                final Dimension options = list.getPreferredSize();
                if (options.height <= MENU_MAX_HEIGHT) return options;

                return new Dimension(options.width + getVerticalScrollBar().getPreferredSize().width, MENU_MAX_HEIGHT);
            }
        };
        scroll.setBorder(null);
        scroll.getVerticalScrollBar().setUnitIncrement(MENU_OPTION_HEIGHT);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);

        final JPopupMenu menu = new JPopupMenu();
        menu.setLayout(new BorderLayout());
        menu.add(scroll, BorderLayout.CENTER);

        final MouseAdapter picker = new MouseAdapter() {
            @Override
            public void mouseMoved(MouseEvent e) {
                list.setSelectedIndex(list.locationToIndex(e.getPoint()));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                list.clearSelection();
            }

            @Override
            public void mouseClicked(MouseEvent e) {
                final int index = list.locationToIndex(e.getPoint());
                if (index < 0) return;

                menu.setVisible(false);
                final int productItemId = options.get(index).getItemId();
                if (productItemId != row.getProductItemId()) {
                    onProductSelected.accept(row.getRootItemId(), productItemId);
                }
            }
        };
        list.addMouseListener(picker);
        list.addMouseMotionListener(picker);

        return menu;
    }

    private static JPanel buildDetail(RowView row) {
        final JPanel detail = new JPanel(new DynamicGridLayout(0, 1, 0, 1));
        detail.setBorder(new EmptyBorder(4, 8, 6, 8));

        if (!row.getXpByItem().isEmpty()) {
            detail.add(heading("By item"));
            for (RowView.Line line : row.getXpByItem()) {
                detail.add(lineOf(line.getName(), Amounts.abbreviate(line.getAmount()), ColorScheme.LIGHT_GRAY_COLOR));
            }
        }

        if (!row.getXpByRecipe().isEmpty()) {
            detail.add(heading("By recipe"));
            for (RowView.RecipeLine line : row.getXpByRecipe()) {
                detail.add(recipeLineOf(line));
            }
        }

        if (!row.getSecondaryDemand().isEmpty()) {
            detail.add(heading("Secondaries"));
            for (RowView.Line line : row.getSecondaryDemand()) {
                detail.add(lineOf(line.getName(), Amounts.abbreviate(line.getAmount()), ColorScheme.LIGHT_GRAY_COLOR));
            }
        }

        return detail;
    }

    private static JLabel heading(String text) {
        final JLabel label = smallLabel(text);
        label.setForeground(ColorScheme.BRAND_ORANGE);

        return label;
    }

    /**
     * The output is what gets cut short when the panel is narrow, so the input always reads in full.
     */
    private static JPanel recipeLineOf(RowView.RecipeLine recipe) {
        final JLabel input = smallLabel(recipe.getInputName());
        input.setIcon(new RightArrowIcon(ColorScheme.LIGHT_GRAY_COLOR));
        input.setHorizontalTextPosition(SwingConstants.LEFT);
        input.setIconTextGap(4);

        final JPanel names = new JPanel(new BorderLayout(4, 0));
        names.setOpaque(false);
        names.add(input, BorderLayout.WEST);
        names.add(smallLabel(recipe.getOutputName()), BorderLayout.CENTER);

        final JPanel line = new JPanel(new BorderLayout(6, 0));
        line.setOpaque(false);
        line.add(names, BorderLayout.CENTER);
        line.add(smallLabel(Amounts.abbreviate(recipe.getXp())), BorderLayout.EAST);

        return line;
    }

    /**
     * The name is what gets cut short when the panel is narrow, so the amount always shows.
     */
    static JPanel lineOf(String name, String amount, Color amountColor) {
        final JLabel amountLabel = smallLabel(amount);
        amountLabel.setForeground(amountColor);

        final JPanel line = new JPanel(new BorderLayout(6, 0));
        line.setOpaque(false);
        line.add(smallLabel(name), BorderLayout.CENTER);
        line.add(amountLabel, BorderLayout.EAST);

        return line;
    }

    private static JLabel smallLabel(String text) {
        final JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        return label;
    }
}

package adamski.ui;

import lombok.Value;

import java.util.List;

/**
 * One row as the panel shows it, with every name already resolved. Built on the client thread,
 * where ItemManager can be used, and drawn on the EDT, where it cannot.
 */
@Value
class RowView {
    /**
     * What a product is picked against - the app needs it back.
     */
    int rootItemId;
    String rootItemName;
    double rootQuantity;


    double xp;

    int productItemId;

    boolean switchedOff;
    String productName;
    double outputQuantity;
    boolean amuletUsed;

    List<ProductOption> productOptions;

    List<Line> xpByItem;

    List<RecipeLine> xpByRecipe;

    List<Line> secondaryDemand;

    @Value
    static class ProductOption {
        int itemId;
        String name;
    }

    @Value
    static class Line {
        double amount;
        String name;
    }

    @Value
    static class RecipeLine {
        double xp;
        String inputName;
        String outputName;
    }
}

package adamski.ui;

import adamski.domain.result.AlchemistAmuletOption;
import adamski.domain.result.ChainItemXp;
import adamski.domain.result.ChainRecipeXp;
import adamski.domain.result.ChainResult;
import adamski.data.PotionDoses;
import adamski.domain.ItemQuantities;
import adamski.domain.Recipe;
import adamski.domain.RecipeTag;
import adamski.domain.balance.SecondaryBalance;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Turns results into what the panel shows, every name resolved. Runs on the client thread, where
 * ItemManager can resolve names; tests pass a map instead.
 */
final class RowViewFactory {
    static final String MAKE_NOTHING = "Make nothing";
    static final String NEEDED = "Needed";
    static final String HELD = "Held";

    // everything is counted in single doses, so the "(1)" on a potion's name says nothing
    private static final Pattern ONE_DOSE_SUFFIX = Pattern.compile("\\s*\\(1\\)$");

    private static final List<RecipeTag> STEP_ORDER = List.of(RecipeTag.SEED, RecipeTag.DEGRIME, RecipeTag.UNF);

    private final IntFunction<String> nameOf;

    private final Map<Integer, List<Recipe>> productRecipesByItem;

    RowViewFactory(IntFunction<String> nameOf, Map<Integer, List<Recipe>> productRecipesByItem) {
        this.nameOf = itemId -> PotionDoses.isPotion(itemId)
                ? ONE_DOSE_SUFFIX.matcher(nameOf.apply(itemId)).replaceFirst("")
                : nameOf.apply(itemId);
        this.productRecipesByItem = productRecipesByItem;
    }

    RowView rowOf(ChainResult chain, boolean amuletUsed) {
        final int rootItemId = chain.getRootItemId();
        final List<RowView.ProductOption> options = new ArrayList<>();

        // picking the root as its own product is how the app is told to make nothing
        options.add(new RowView.ProductOption(rootItemId, MAKE_NOTHING));
        for (Recipe recipe : inMenuOrder(productRecipesByItem.getOrDefault(rootItemId, List.of()))) {
            final int productItemId = recipe.getOutput().getItemId();
            options.add(new RowView.ProductOption(productItemId, nameOf.apply(productItemId)));
        }

        // a stopped row's root is listed as held, but contributes nothing worth a line
        final List<RowView.Line> xpByItem = new ArrayList<>();
        for (ChainItemXp contribution : chain.getItemContributions()) {
            if (contribution.getXp() != 0) {
                xpByItem.add(new RowView.Line(contribution.getXp(),
                        Amounts.abbreviate(contribution.getQuantity()) + " × " + nameOf.apply(contribution.getItemId())));
            }
        }

        final List<RowView.RecipeLine> xpByRecipe = new ArrayList<>();
        for (ChainRecipeXp contribution : chain.getRecipeContributions()) {
            xpByRecipe.add(new RowView.RecipeLine(contribution.getXp(),
                    nameOf.apply(contribution.getRecipe().getPrimary().getItemId()),
                    nameOf.apply(contribution.getRecipe().getOutput().getItemId())));
        }

        final int productItemId = chain.getProductItemId();

        return new RowView(
                rootItemId,
                nameOf.apply(rootItemId),
                chain.getRootQuantity(),
                chain.getXp(),
                productItemId,
                chain.makesNothing(),
                chain.makesNothing() ? MAKE_NOTHING : nameOf.apply(productItemId),
                chain.getOutputQuantity(),
                amuletUsed,
                options,
                xpByItem,
                xpByRecipe,
                secondaryDemandLinesOf(chain.getSecondaryDemand()));
    }

    /**
     * The steps before a potion first - seed, degrime, unf - then the rest by level.
     */
    private static List<Recipe> inMenuOrder(List<Recipe> productRecipes) {
        final List<Recipe> ordered = new ArrayList<>(productRecipes);
        ordered.sort(Comparator
                .comparingInt(RowViewFactory::stepRankOf)
                .thenComparingInt(recipe -> isStep(recipe) ? 0 : recipe.getLevel()));
        return ordered;
    }

    private static int stepRankOf(Recipe recipe) {
        return isStep(recipe) ? STEP_ORDER.indexOf(recipe.getTag()) : STEP_ORDER.size();
    }

    private static boolean isStep(Recipe recipe) {
        return STEP_ORDER.contains(recipe.getTag());
    }

    /**
     * Shortfalls first, as negatives, then what is spare.
     */
    List<SecondaryView> secondariesOf(SecondaryBalance balance) {
        return balance.getEntries().stream()
                .sorted(Comparator.comparingDouble(SecondaryBalance.BalanceEntry::net))
                .map(this::secondaryOf)
                .collect(Collectors.toList());
    }

    private SecondaryView secondaryOf(SecondaryBalance.BalanceEntry secondary) {
        final List<RowView.Line> breakdown = new ArrayList<>();
        breakdown.add(new RowView.Line(secondary.getQtyDemanded(), NEEDED));
        breakdown.add(new RowView.Line(secondary.getQtyHeld(), HELD));

        secondary.getChainContributions().stream()
                .sorted(Comparator.comparingDouble(SecondaryBalance.ChainContribution::getMakes).reversed())
                .forEach(chain -> breakdown.add(new RowView.Line(chain.getMakes(), nameOf.apply(chain.getRootItemId()))));

        // every kind of bird nest is called "Bird nest", so precursors are summed by name
        final Map<String, double[]> heldAndMadeByName = new LinkedHashMap<>();
        for (SecondaryBalance.PrecursorContribution precursor : secondary.getPrecursorContributions()) {
            final double[] heldAndMade = heldAndMadeByName.computeIfAbsent(nameOf.apply(precursor.getPrecursorItemId()), name -> new double[2]);
            heldAndMade[0] += precursor.getHeld();
            heldAndMade[1] += precursor.getMakes();
        }

        heldAndMadeByName.entrySet().stream()
                .sorted(Comparator.comparingDouble((Map.Entry<String, double[]> entry) -> entry.getValue()[1]).reversed())
                .forEach(entry -> breakdown.add(new RowView.Line(entry.getValue()[1],
                        Amounts.abbreviate(entry.getValue()[0]) + " × " + entry.getKey())));

        final int secondaryItemId = secondary.getSecondaryItemId();
        return new SecondaryView(secondaryItemId, nameOf.apply(secondaryItemId), secondary.net(), breakdown);
    }

    AmuletView amuletOf(List<AlchemistAmuletOption> options, double charges) {
        final List<AmuletView.Line> lines = options.stream()
                .map(option -> new AmuletView.Line(
                        option.getRecipeId(),
                        nameOf.apply(option.getProductItemId()),
                        option.getDosesPerPotionOptions(),
                        option.getDosesPerPotion()))
                .collect(Collectors.toList());

        return new AmuletView(charges, lines);
    }

    /**
     * Rounded up: a fraction of a secondary still means gathering a whole one.
     */
    private List<RowView.Line> secondaryDemandLinesOf(ItemQuantities demand) {
        return demand.asMap().entrySet().stream()
                .sorted(Map.Entry.<Integer, Double>comparingByValue().reversed())
                .map(entry -> new RowView.Line(Math.ceil(entry.getValue()), nameOf.apply(entry.getKey())))
                .collect(Collectors.toList());
    }
}

package adamski.ui;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;

import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;

/**
 * One secondary's net, folding open to its breakdown. Rebuilt for every result.
 */
class SecondaryPanel extends JPanel {
    private static final Color HOVER = RowPanel.ROOT_HOVER;


    // on the line rather than the block, so the hover reaches the block's edges
    private static final int SIDE_PADDING = 6;

    // taller than a plain line, so it is easier to click
    private static final float EXTRA_HEIGHT = 0.2f;

    SecondaryPanel(SecondaryView secondary, boolean expanded, Consumer<Boolean> onToggle) {
        setLayout(new BorderLayout());
        setOpaque(false);

        final Color netColor = secondary.getNet() < 0
                ? ColorScheme.PROGRESS_ERROR_COLOR
                : ColorScheme.PROGRESS_COMPLETE_COLOR;
        final JPanel summary = RowPanel.lineOf(secondary.getName(), Amounts.abbreviate(secondary.getNet()), netColor);
        summary.setBackground(HOVER);

        final int padding = Math.round(summary.getPreferredSize().height * EXTRA_HEIGHT / 2);
        summary.setBorder(new EmptyBorder(padding, SIDE_PADDING, padding, SIDE_PADDING));

        final JPanel detail = new JPanel(new DynamicGridLayout(0, 1, 0, 1));
        detail.setBackground(RowPanel.DETAIL_SHADE);
        detail.setBorder(new EmptyBorder(3, SIDE_PADDING + 8, 4, SIDE_PADDING));
        for (RowView.Line line : secondary.getBreakdown()) {
            detail.add(RowPanel.lineOf(line.getName(), Amounts.abbreviate(line.getAmount()), ColorScheme.LIGHT_GRAY_COLOR));
        }
        detail.setVisible(expanded);

        summary.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                final boolean nowExpanded = !detail.isVisible();
                detail.setVisible(nowExpanded);
                onToggle.accept(nowExpanded);
                revalidate();
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                summary.setOpaque(true);
                summary.repaint();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                summary.setOpaque(false);
                summary.repaint();
            }
        });
        summary.setToolTipText("Click for what is needed and held");
        summary.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        add(summary, BorderLayout.NORTH);
        add(detail, BorderLayout.CENTER);
    }
}

