package adamski.ui;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;

/**
 * A heading that folds its section open and shut.
 */
final class SectionHeading extends JPanel {
    private static final Color TEXT = Color.WHITE;
    private static final Color HOVER = ColorScheme.BRAND_ORANGE;

    private final JLabel title;

    // the default font, since the RuneScape ones may lack the arrows
    private final JLabel arrow = new JLabel();

    private boolean expanded;

    /**
     * @param info   shown on the right, folding the section when clicked (the amulet's charges); may be null
     * @param button shown on the right with clicks of its own (the recipes' eye); may be null
     */
    SectionHeading(String text, boolean expanded, Consumer<Boolean> onToggle, JComponent info, JComponent button) {
        super(new BorderLayout());
        setOpaque(false);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        this.expanded = expanded;

        title = new JLabel(text);
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(TEXT);

        arrow.setForeground(TEXT);
        arrow.setText(arrowOf(expanded));

        final JPanel extras = new JPanel(new BorderLayout(6, 0));
        extras.setOpaque(false);
        if (info != null) extras.add(info, BorderLayout.CENTER);
        if (button != null) extras.add(button, BorderLayout.EAST);

        final JPanel right = new JPanel(new BorderLayout(6, 0));
        right.setOpaque(false);
        right.add(extras, BorderLayout.CENTER);
        right.add(arrow, BorderLayout.EAST);

        add(title, BorderLayout.WEST);
        add(right, BorderLayout.EAST);

        final MouseAdapter folds = new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                SectionHeading.this.expanded = !SectionHeading.this.expanded;
                arrow.setText(arrowOf(SectionHeading.this.expanded));
                onToggle.accept(SectionHeading.this.expanded);
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                setHovered(true);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                setHovered(false);
            }
        };
        addMouseListener(folds);
        // a tooltip makes a label take its own mouse events, so the info needs telling too
        if (info != null) info.addMouseListener(folds);
    }

    private void setHovered(boolean hovered) {
        final Color color = hovered ? HOVER : TEXT;
        title.setForeground(color);
        arrow.setForeground(color);
    }

    private static String arrowOf(boolean expanded) {
        return expanded ? "▾" : "▸";
    }
}

package adamski.ui;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.JComponent;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Rectangle2D;

/**
 * "85 ▸ 92" - the level now and once the bank is made - above a line showing how far the bank gets
 * through its last level. The arrow is drawn, since the RuneScape font has no good one. EDT only.
 */
final class XpBar extends JComponent {
    private static final Color TRACK = ColorScheme.LIGHT_GRAY_COLOR;
    private static final Color FILL = new Color(0x3A, 0x8E, 0xE6);

    // what is already held of the level, shown when the bank gains no level
    private static final Color COVERED = new Color(0x3A, 0x58, 0x7A);
    private static final Color LEVEL_TEXT = ColorScheme.LIGHT_GRAY_COLOR;
    private static final Color XP_TEXT = Color.WHITE;

    private static final int LINE_THICKNESS = 2;

    private static final int TEXT_GAP = 6;

    private static final int ARROW_GAP = 5;

    private XpBarView view;

    XpBar() {
        final FontMetrics above = getFontMetrics(FontManager.getRunescapeFont());
        final FontMetrics below = getFontMetrics(FontManager.getRunescapeFont());
        setPreferredSize(new Dimension(0, heightOf(above) + TEXT_GAP + LINE_THICKNESS + TEXT_GAP + heightOf(below)));
    }

    void setView(XpBarView view) {
        this.view = view;
        setToolTipText(String.format("Level %d now, %d once %,.0f banked xp is made",
                view.getCurrentLevel(), view.getBankedLevel(), view.getBankedXp()));
        repaint();
    }

    @Override
    protected void paintComponent(Graphics graphics) {
        if (view == null) return;

        final Graphics2D g = (Graphics2D) graphics.create();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            final int width = getWidth();

            g.setFont(FontManager.getRunescapeFont());
            final FontMetrics above = g.getFontMetrics();
            paintTitle(g, above, width);

            final int lineTop = heightOf(above) + TEXT_GAP;
            // once a level is gained nothing is held of it, so the line is all bank
            final int start = (int) Math.round(width * view.getStartProgress());
            final int end = (int) Math.round(width * view.getProgress());
            g.setColor(TRACK);
            g.fillRect(0, lineTop, width, LINE_THICKNESS);
            g.setColor(COVERED);
            g.fillRect(0, lineTop, start, LINE_THICKNESS);
            g.setColor(FILL);
            g.fillRect(start, lineTop, end - start, LINE_THICKNESS);

            g.setFont(FontManager.getRunescapeFont());
            final FontMetrics metrics = g.getFontMetrics();
            final int baseline = lineTop + LINE_THICKNESS + TEXT_GAP + metrics.getAscent();

            final String banked = String.valueOf(view.getBankedLevel());
            final String next = String.valueOf(view.getNextLevel());
            final String xp = xpText(view.getBankedXp());

            g.setColor(LEVEL_TEXT);
            g.drawString(banked, 0, baseline);
            g.drawString(next, width - metrics.stringWidth(next), baseline);

            g.setColor(XP_TEXT);
            g.drawString(xp, (width - metrics.stringWidth(xp)) / 2, baseline);
        } finally {
            g.dispose();
        }
    }

    private static int heightOf(FontMetrics metrics) {
        return metrics.getAscent() + metrics.getDescent();
    }

    /**
     * Centred on the arrow, so a three-digit level does not push it off centre.
     */
    private void paintTitle(Graphics2D g, FontMetrics metrics, int width) {
        final String from = String.valueOf(view.getCurrentLevel());
        final int baseline = metrics.getAscent();
        g.setColor(XP_TEXT);

        if (!view.levelGained()) {
            g.drawString(from, (width - metrics.stringWidth(from)) / 2, baseline);
            return;
        }

        final String to = String.valueOf(view.getBankedLevel());

        final Rectangle2D digit = g.getFont().createGlyphVector(g.getFontRenderContext(), "0").getVisualBounds();
        final int halfHeight = Math.max(2, (int) Math.round(digit.getHeight() * 0.3));
        final int arrowWidth = halfHeight + 1;
        final int arrowMiddle = baseline + (int) Math.round(digit.getY() + digit.getHeight() / 2);

        final int arrowLeft = (width - arrowWidth) / 2;
        g.drawString(from, arrowLeft - ARROW_GAP - metrics.stringWidth(from), baseline);
        g.drawString(to, arrowLeft + arrowWidth + ARROW_GAP, baseline);

        g.setColor(LEVEL_TEXT);
        paintArrow(g, arrowLeft, arrowMiddle, halfHeight);
    }

    /**
     * Built from one-pixel columns so it stays as crisp as the pixel font around it.
     */
    private static void paintArrow(Graphics2D g, int left, int middle, int halfHeight) {
        for (int column = 0; column <= halfHeight; column++) {
            final int reach = halfHeight - column;
            g.fillRect(left + column, middle - reach, 1, 2 * reach + 1);
        }
    }

    /**
     * Short but precise enough to watch move: "+3.179m xp", "+450.1k xp", "+820 xp".
     */
    static String xpText(double xp) {
        final String amount;
        if (xp >= 1_000_000) {
            amount = String.format("%.3fm", xp / 1_000_000);
        } else if (xp >= 1_000) {
            amount = String.format("%.1fk", xp / 1_000);
        } else {
            amount = String.format("%.0f", xp);
        }

        return "+" + amount + " xp";
    }
}

package adamski.ui;

import lombok.Value;
import net.runelite.api.Experience;

/**
 * Virtual levels count, up to 126.
 */
@Value
class XpBarView {
    int currentLevel;

    int bankedLevel;

    int nextLevel;

    /**
     * How far through the banked level towards the next, 0 to 1.
     */
    double progress;

    /**
     * How far through the level the player already is when the bank gains no level; otherwise 0.
     */
    double startProgress;

    double bankedXp;

    static XpBarView of(int currentXp, double bankedXp) {
        final int afterXp = (int) Math.min(Experience.MAX_SKILL_XP, currentXp + Math.max(0, bankedXp));
        final int bankedLevel = Experience.getLevelForXp(afterXp);

        final int currentLevel = Experience.getLevelForXp(currentXp);

        return new XpBarView(currentLevel, bankedLevel,
                Math.min(bankedLevel + 1, Experience.MAX_VIRT_LEVEL),
                progressThrough(bankedLevel, afterXp),
                bankedLevel > currentLevel ? 0 : progressThrough(currentLevel, currentXp),
                bankedXp);
    }

    boolean levelGained() {
        return bankedLevel > currentLevel;
    }

    private static double progressThrough(int level, int xp) {
        if (level >= Experience.MAX_VIRT_LEVEL) return 1;

        final int start = Experience.getXpForLevel(level);
        final int end = Experience.getXpForLevel(level + 1);

        return (double) (xp - start) / (end - start);
    }
}

