/**
 * Drives the whole pipeline against the real recipe table, so these numbers move if it does.
 */
public class HerbloreAppTest {
    private static final double DELTA = 0.0001;

    /**
     * r5 degrime 7.5, r20 unf 0, r44 defence potion 75. Terminal - caviar mixes run off caviar.
     */
    private static final double GRIMY_RANARR_XP = 82.5;

    private static final RecipeGraph GRAPH = new RecipeGraph(Recipes.all());

    private HerbloreApp app;

    @Before
    public void setUp() {
        app = new HerbloreApp(new HerbloreStore(), GRAPH, SecondaryPrecursors.all());
    }

    @Test
    public void noResultUntilASourceIsRead() {
        assertNull(app.getResult());
    }

    @Test
    public void emptyBankIsZero() {
        final HerbloreResult result = bank(new HashMap<>());

        assertEquals(0, result.getTotalXp(), DELTA);
        assertTrue(result.getChainResults().isEmpty());
    }

    @Test
    public void terminalItemContributesNothing() {
        assertEquals(0, bank(items(ItemID.BRUTAL_1DOSE1DEFENSE, 4)).getTotalXp(), DELTA);
    }

    @Test
    public void grimyHerbIsWorthItsWholeChain() {
        final HerbloreResult result = bank(items(ItemID.UNIDENTIFIED_RANARR, 1));

        assertEquals(GRIMY_RANARR_XP, result.getTotalXp(), DELTA);
        assertEquals(7.5, xpByRecipe(result).get(5), DELTA);   // degrime
        assertEquals(75.0, xpByRecipe(result).get(44), DELTA); // defence potion
    }

    @Test
    public void caviarMixesAreDrivenByCaviarNotByThePotion() {
        // A defence potion on its own goes nowhere - the mix consumes brutal caviar
        assertEquals(0, bank(items(ItemID._1DOSE1DEFENSE, 10)).getTotalXp(), DELTA);

        // r95 energy mix, first caviar recipe in the table, 23xp per caviar
        final HerbloreResult caviar = bank(items(ItemID.BRUT_CAVIAR, 4));

        assertEquals(92.0, caviar.getTotalXp(), DELTA);
        assertEquals(92.0, xpByRecipe(caviar).get(95), DELTA);
    }

    @Test
    public void onlyOneCaviarMixIsReachableUntilConfigLands() {
        // All 23 mixes share brutal caviar, so first in table order takes the lot
        final HerbloreResult result = bank(items(ItemID.BRUT_CAVIAR, 1));

        assertEquals(1, xpByRecipe(result).size());
    }

    @Test
    public void zeroXpStepsAreOmittedFromTheBreakdown() {
        // r20 turns ranarr into ranarr unf and is worth nothing
        assertFalse(xpByRecipe(bank(items(ItemID.UNIDENTIFIED_RANARR, 1))).containsKey(20));
    }

    @Test
    public void totalIsTheSumOfTheBreakdown() {
        final HerbloreResult result = bank(items(ItemID.UNIDENTIFIED_RANARR, 13));

        final double summed = xpByRecipe(result).values().stream().mapToDouble(Double::doubleValue).sum();

        assertEquals(summed, result.getTotalXp(), DELTA);
    }

    @Test
    public void seedsCountAtTheDefaultYield() {
        // r122 yields DEFAULT_HERB_YIELD grimy ranarr and is itself worth no xp
        assertEquals(Recipes.DEFAULT_HERB_YIELD * GRIMY_RANARR_XP, bank(items(ItemID.RANARR_SEED, 1)).getTotalXp(), DELTA);
    }

    @Test
    public void aSeedYieldSettingReplacesTheDefault() {
        bank(items(ItemID.RANARR_SEED, 2));

        app.applySettings(HerbloreSettings.DEFAULT.withSeedYieldByItemId(Map.of(ItemID.RANARR_SEED, 10.0)));

        assertEquals(2 * 10.0 * GRIMY_RANARR_XP, app.getResult().getTotalXp(), DELTA);
    }

    /**
     * Seeds and frags left uncounted are as if not held - wherever they are held. Leaping sturgeon
     * are cut, not grown, so they still count.
     */
    @Test
    public void seedsLeftUncountedMatchABankWithoutThem() {
        final Map<Integer, Integer> bank = new HashMap<>();
        bank.put(ItemID.UNIDENTIFIED_RANARR, 3);
        bank.put(ItemID.BRUT_STURGEON, 4);
        bank.put(ItemID.CORAL_ELKHORN_FRAG, 2);

        final Map<ItemSource, ItemQuantities> sources = source(ItemSource.Bank, bank);
        sources.put(ItemSource.SeedVault, ItemQuantities.counted(items(ItemID.RANARR_SEED, 5)));
        app.updateItems(sources);
        app.applySettings(HerbloreSettings.DEFAULT.withSeedsCounted(false));

        final Map<Integer, Integer> withoutSeeds = new HashMap<>(bank);
        withoutSeeds.remove(ItemID.CORAL_ELKHORN_FRAG);
        final HerbloreApp seedless = new HerbloreApp(new HerbloreStore(), GRAPH, SecondaryPrecursors.all());
        seedless.updateItems(source(ItemSource.Bank, withoutSeeds));

        assertEquals(seedless.getResult(), app.getResult());
    }

    @Test
    public void countingSeedsAgainRestoresTheirXp() {
        final double counted = bank(items(ItemID.RANARR_SEED, 2)).getTotalXp();

        app.applySettings(HerbloreSettings.DEFAULT.withSeedsCounted(false));
        assertEquals(0, app.getResult().getTotalXp(), DELTA);

        app.applySettings(HerbloreSettings.DEFAULT);
        assertEquals(counted, app.getResult().getTotalXp(), DELTA);
    }

    @Test
    public void prescriptionGogglesSavingCaviarMakeMoreMixes() {
        bank(items(ItemID.BRUT_CAVIAR, 9));

        app.applySettings(HerbloreSettings.DEFAULT.withPrescriptionGogglesUsed(true));

        // r95 energy mix, 23xp a run, and 9 caviar now run 10 times
        assertEquals(230.0, app.getResult().getTotalXp(), DELTA);
    }

    @Test
    public void prescriptionGogglesSavingASecondaryLeaveXpAlone() {
        // torstol's default route ends at r60 zamorak brew, which saves the jangerberries
        final HerbloreResult before = bank(items(ItemID.TORSTOL, 10));

        app.applySettings(HerbloreSettings.DEFAULT.withPrescriptionGogglesUsed(true));
        final ChainResult after = app.getResult().getChainResults().get(0);

        assertEquals(before.getTotalXp(), app.getResult().getTotalXp(), DELTA);
        assertEquals(9.0, after.getSecondaryDemand().get(ItemID.JANGERBERRIES), DELTA);
    }

    @Test
    public void theDegrimeSpellHalvesTheCleaningXp() {
        bank(items(ItemID.UNIDENTIFIED_RANARR, 1));

        app.applySettings(HerbloreSettings.DEFAULT.withDegrimeMethod(DegrimeMethod.SPELL));

        // r5 degrime is 7.5 of the 82.5, so half of it goes
        assertEquals(GRIMY_RANARR_XP - 3.75, app.getResult().getTotalXp(), DELTA);
    }

    @Test
    public void zahurCleaningGivesNoCleaningXpButKeepsTheRestOfTheChain() {
        bank(items(ItemID.UNIDENTIFIED_RANARR, 1));

        app.applySettings(HerbloreSettings.DEFAULT.withDegrimeMethod(DegrimeMethod.ZAHUR));

        assertEquals(GRIMY_RANARR_XP - 7.5, app.getResult().getTotalXp(), DELTA);
        assertEquals(1, app.getResult().getChainResults().size());
    }

    /**
     * r44, ranarr unf to a 3-dose defence potion, 75xp.
     */
    private static final int DEFENCE_RECIPE = 44;

    /**
     * r87, super energy to stamina a dose at a time, then r89 to extended stamina, 27.5xp a dose.
     */
    private static final int STAMINA_RECIPE = 87;
    private static final int EXTENDED_STAMINA_RECIPE = 89;

    @Test
    public void theAmuletAddsDosesButNoXpToItsOwnRecipe() {
        useAmulet();
        final double before = bank(items(ItemID.RANARRVIAL, 10)).getTotalXp();

        app.setAmuletDoses(DEFENCE_RECIPE, 3);
        final HerbloreResult result = app.getResult();

        assertEquals(31.5, result.getChainResults().get(0).getOutputQuantity(), DELTA); // 30 + 10 × 0.15
        assertEquals(before, result.getTotalXp(), DELTA);
        assertEquals(1.5, result.getAmuletCharges(), DELTA);
        assertEquals(Set.of(ItemID.RANARRVIAL), result.getAmuletChainRootItemIds());
    }

    /**
     * Upgrading smaller potions makes more doses, which the next recipe turns into xp.
     */
    @Test
    public void theSizeUpgradedChangesTheDosesAndTheXpAfter() {
        useAmulet();
        bank(items(ItemID._1DOSE2ENERGY, 30));

        app.setAmuletDoses(STAMINA_RECIPE, 3);
        assertEquals(1.5, app.getResult().getAmuletCharges(), DELTA);
        assertEquals(31.5 * 27.5, xpByRecipe(app.getResult()).get(EXTENDED_STAMINA_RECIPE), DELTA);

        app.setAmuletDoses(STAMINA_RECIPE, 1);
        assertEquals(4.5, app.getResult().getAmuletCharges(), DELTA);
        assertEquals(34.5 * 27.5, xpByRecipe(app.getResult()).get(EXTENDED_STAMINA_RECIPE), DELTA);
    }

    @Test
    public void onlyPotionsTheBankMakesAreOffered() {
        useAmulet();
        assertTrue(bank(items(ItemID.BRUTAL_1DOSE1DEFENSE, 4)).getAmuletOptions().isEmpty());

        final List<AlchemistAmuletOption> options = bank(items(ItemID.RANARRVIAL, 10)).getAmuletOptions();

        assertEquals(1, options.size());
        assertEquals(DEFENCE_RECIPE, options.get(0).getRecipeId());
        assertEquals(ItemID._1DOSE1DEFENSE, options.get(0).getProductItemId());
        assertFalse(options.get(0).isUsed());
    }

    @Test
    public void anUpgradeOffersEverySizeAndAWholePotionOnlyThree() {
        useAmulet();
        bank(items(ItemID._1DOSE2ENERGY, 30));

        final AlchemistAmuletOption stamina = app.getResult().getAmuletOptions().stream()
                .filter(option -> option.getRecipeId() == STAMINA_RECIPE)
                .findFirst().orElseThrow();
        assertEquals(List.of(3, 2, 1), stamina.getDosesPerPotionOptions());

        assertEquals(List.of(3), bank(items(ItemID.RANARRVIAL, 10)).getAmuletOptions().get(0).getDosesPerPotionOptions());
    }

    /**
     * Switched off, the choices are kept but count for nothing, and none are offered - so nothing
     * hidden changes the numbers.
     */
    @Test
    public void switchedOffTheAmuletAddsNothingButKeepsItsChoices() {
        useAmulet();
        final double before = bank(items(ItemID.RANARRVIAL, 10)).getChainResults().get(0).getOutputQuantity();
        app.setAmuletDoses(DEFENCE_RECIPE, 3);

        app.applySettings(HerbloreSettings.DEFAULT);

        assertEquals(before, app.getResult().getChainResults().get(0).getOutputQuantity(), DELTA);
        assertEquals(0, app.getResult().getAmuletCharges(), DELTA);
        assertTrue(app.getResult().getAmuletOptions().isEmpty());
        assertTrue(app.getResult().getAmuletChainRootItemIds().isEmpty());

        useAmulet();
        assertEquals(1.5, app.getResult().getAmuletCharges(), DELTA);
    }

    @Test
    public void aSizeTheRecipeCannotBeMadeInIsRefused() {
        useAmulet();
        bank(items(ItemID.RANARRVIAL, 10));
        final List<Map<Integer, Integer>> told = listenForAmulet();

        app.setAmuletDoses(DEFENCE_RECIPE, 1); // a whole potion is always 3
        app.setAmuletDoses(999, 3);           // no such recipe

