    /**
     * 10 torstol sent straight to super combat, and 10 irit vials on their default, super attack.
     */
    private Map<Integer, Integer> superCombats() {
        app.selectProduct(ItemID.TORSTOL, ItemID._1DOSE2COMBAT);

        final Map<Integer, Integer> bank = items(ItemID.TORSTOL, 10);
        bank.put(ItemID.IRITVIAL, 10);
        return bank;
    }

    private SecondaryBalance.BalanceEntry superAttackEntryOf(Map<Integer, Integer> bankItems) {
        return bankBalance(bankItems).getEntries().stream()
                .filter(entry -> entry.getSecondaryItemId() == ItemID._1DOSE2ATTACK)
                .findFirst()
                .orElseThrow();
    }

    /**
     * Banks the items with toadflax vials going to saradomin brews - each needs a crushed nest.
     */
    private HerbloreResult brew(Map<Integer, Integer> bankItems) {
        app.selectProduct(ItemID.TOADFLAXVIAL, ItemID._1DOSEPOTIONOFSARADOMIN);
        return bank(bankItems);
    }

    private SecondaryBalance brewBalance(Map<Integer, Integer> bankItems) {
        return brew(bankItems).getSecondaryBalance();
    }

    private List<HerbloreResult> listenForResults() {
        final List<HerbloreResult> published = new ArrayList<>();
        app.addResultListener(published::add);
        return published;
    }

    private void useAmulet() {
        app.applySettings(HerbloreSettings.DEFAULT.withAlchemistsAmuletUsed(true));
    }

    private List<Map<Integer, Integer>> listenForAmulet() {
        final List<Map<Integer, Integer>> told = new ArrayList<>();
        app.addAmuletListener(told::add);
        return told;
    }

    private List<RecipeSelection> listenForSelections() {
        final List<RecipeSelection> told = new ArrayList<>();
        app.addSelectionListener(told::add);
        return told;
    }

    /**
     * What a pick of hunting potions on grimy avantoe leaves behind, as a save would hold it.
     */
    private static RecipeSelection pickedAvantoeHunting() {
        final HerbloreApp picker = new HerbloreApp(new HerbloreStore(), GRAPH, SecondaryPrecursors.all());
        final List<RecipeSelection> told = new ArrayList<>();
        picker.addSelectionListener(told::add);
        picker.selectProduct(ItemID.UNIDENTIFIED_AVANTOE, ItemID._1DOSEHUNTING);
        return told.get(0);
    }

    private HerbloreResult bank(Map<Integer, Integer> bankItems) {
        app.updateItems(source(ItemSource.Bank, bankItems));
        return app.getResult();
    }

    /**
     * The recipe contributions of every chainResult, flattened - a recipe belongs to one chainResult, so nothing collides.
     */
    private static Map<Integer, Double> xpByRecipe(HerbloreResult result) {
        return result.getChainResults().stream()
                .flatMap(chainResult -> chainResult.getRecipeContributions().stream())
                .collect(Collectors.toMap(step -> step.getRecipe().getId(), ChainRecipeXp::getXp));
    }

    private SecondaryBalance bankBalance(Map<Integer, Integer> bankItems) {
        app.updateItems(source(ItemSource.Bank, bankItems));
        return app.getResult().getSecondaryBalance();
    }

    private static Map<ItemSource, ItemQuantities> source(ItemSource source, Map<Integer, Integer> items) {
        final Map<ItemSource, ItemQuantities> snapshot = new EnumMap<>(ItemSource.class);
        snapshot.put(source, ItemQuantities.counted(items));
        return snapshot;
    }

    private static Map<Integer, Integer> items(int itemId, int quantity) {
        final Map<Integer, Integer> items = new HashMap<>();
        items.put(itemId, quantity);
        return items;
    }
}

package adamski.app;

import adamski.domain.ItemQuantities;
import adamski.domain.ItemSource;
import adamski.domain.route.RecipeSelection;
import org.junit.Before;
import org.junit.Test;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class HerbloreStoreTest {
    private HerbloreStore store;

    @Before
    public void setUp() {
        store = new HerbloreStore();
    }

    @Test
    public void aFirstReadIsAChange() {
        assertTrue(store.updateItems(batch(ItemSource.Bank, items(1, 10, 2, 20))));
    }

    @Test
    public void anUnchangedResubmissionIsNoChange() {
        store.updateItems(batch(ItemSource.Bank, items(1, 10)));

        assertFalse(store.updateItems(batch(ItemSource.Bank, items(1, 10))));
    }

    @Test
    public void aMovedQuantityIsAChange() {
        store.updateItems(batch(ItemSource.Bank, items(1, 10)));

        assertTrue(store.updateItems(batch(ItemSource.Bank, items(1, 13))));
    }

    @Test
    public void anUnchangedSourceDoesNotHideAMovedOne() {
        final Map<ItemSource, ItemQuantities> first = new EnumMap<>(ItemSource.class);
        first.put(ItemSource.Bank, items(1, 10));
        first.put(ItemSource.PotionStorage, items(2, 5));
        store.updateItems(first);

        final Map<ItemSource, ItemQuantities> second = new EnumMap<>(ItemSource.class);
        second.put(ItemSource.Bank, items(1, 10)); // unchanged
        second.put(ItemSource.PotionStorage, items(2, 8));

        assertTrue(store.updateItems(second));
        assertEquals(items(2, 8), store.itemsBySource().get(ItemSource.PotionStorage));
    }

    @Test
    public void snapshotCarriesEverySourceSeenSoFar() {
        store.updateItems(batch(ItemSource.Bank, items(1, 10)));
        store.updateItems(batch(ItemSource.PotionStorage, items(2, 5)));

        final var snapshot = store.itemsBySource();

        assertEquals(items(1, 10), snapshot.get(ItemSource.Bank));
        assertEquals(items(2, 5), snapshot.get(ItemSource.PotionStorage));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void snapshotIsImmutable() {
        store.updateItems(batch(ItemSource.Bank, items(1, 10)));

        store.itemsBySource().put(ItemSource.PotionStorage, ItemQuantities.EMPTY);
    }

    @Test
    public void snapshotDoesNotObserveALaterApply() {
        store.updateItems(batch(ItemSource.Bank, items(1, 10)));
        final var snapshot = store.itemsBySource();

        store.updateItems(batch(ItemSource.PotionStorage, items(2, 5)));
        store.updateItems(batch(ItemSource.Bank, items(1, 99)));

        assertEquals(1, snapshot.size());
        assertEquals(items(1, 10), snapshot.get(ItemSource.Bank));
    }

    private static Map<ItemSource, ItemQuantities> batch(ItemSource source, ItemQuantities items) {
        final Map<ItemSource, ItemQuantities> batch = new EnumMap<>(ItemSource.class);
        batch.put(source, items);
        return batch;
    }

    /**
     * @param pairs alternating itemId and quantity
     */
    private static ItemQuantities items(int... pairs) {
        final Map<Integer, Integer> items = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2) {
            items.put(pairs[i], pairs[i + 1]);
        }
        return ItemQuantities.counted(items);
    }

    @Test
    public void anUntouchedStoreIsAllDefault() {
        assertEquals(RecipeSelection.ALL_DEFAULT, store.selection());
    }

    @Test
    public void aNewSelectionIsRemembered() {
        final RecipeSelection next = RecipeSelection.of(Map.of(50, 1234));

        assertTrue(store.updateSelection(next));
        assertEquals(next, store.selection());
    }

    @Test
    public void selectingWhatIsAlreadyHeldChangesNothing() {
        store.updateSelection(RecipeSelection.of(Map.of(50, 1234)));

        assertFalse(store.updateSelection(RecipeSelection.of(Map.of(50, 1234))));
    }

    @Test
    public void goingBackToAllDefaultCounts() {
        store.updateSelection(RecipeSelection.of(Map.of(50, 1234)));

        assertTrue(store.updateSelection(RecipeSelection.ALL_DEFAULT));
        assertEquals(RecipeSelection.DEFAULT, store.selection().recipeIdFor(50));
    }
}

package adamski.data;

import adamski.domain.Recipe;
import org.junit.Test;

import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class AlchemistsAmuletTest {
    private static final Map<Integer, Recipe> RECIPES_BY_ID = Recipes.all().stream()
            .collect(Collectors.toMap(Recipe::getId, Function.identity()));

    /**
     * The amulet adds a dose, so what it is used on must make something dosed - not always a
     * potion: the haemostatic dressing is one too.
     */
    @Test
    public void everyListedRecipeMakesSomethingDosed() {
        AlchemistsAmulet.dosesPerPotionOptionsByRecipeId().keySet().forEach(recipeId -> {
            final Recipe recipe = RECIPES_BY_ID.get(recipeId);
            assertNotNull("no recipe " + recipeId, recipe);
            assertTrue("recipe " + recipeId + " makes nothing dosed", PotionDoses.isPotion(recipe.getOutput().getItemId()));
        });
    }

    /**
     * A whole potion's size is what the recipe makes, so it must make 3 - fewer than 4, and the
     * size the extra dose is reckoned against.
     */
    @Test
    public void aWholePotionMakesThreeDoses() {
        AlchemistsAmulet.dosesPerPotionOptionsByRecipeId().forEach((recipeId, options) -> {
            if (options.equals(List.of(3))) {
                assertEquals("recipe " + recipeId, 3.0, RECIPES_BY_ID.get(recipeId).getOutput().getQuantity(), 0);
            }
        });
    }

    /**
     * An upgrade is one dose in, one dose out, so the player's potion size is what it is made in.
     */
    @Test
    public void anUpgradeIsOneDoseAtATime() {
        AlchemistsAmulet.dosesPerPotionOptionsByRecipeId().forEach((recipeId, options) -> {
            if (options.size() > 1) {
                final Recipe recipe = RECIPES_BY_ID.get(recipeId);
                assertEquals("recipe " + recipeId, 1.0, recipe.getPrimary().getQuantity(), 0);
                assertEquals("recipe " + recipeId, 1.0, recipe.getOutput().getQuantity(), 0);
            }
        });
    }

    /**
     * Ticking a potion always picks 3, so every recipe must offer it.
     */
    @Test
    public void everyRecipeCanBeMadeInTheDefaultSize() {
        AlchemistsAmulet.dosesPerPotionOptionsByRecipeId().forEach((recipeId, options) ->
                assertTrue("recipe " + recipeId, options.contains(AlchemistsAmulet.DEFAULT_DOSES_PER_POTION)));
    }

    @Test
    public void noSizeIsFourOrMore() {
        AlchemistsAmulet.dosesPerPotionOptionsByRecipeId().forEach((recipeId, options) ->
                options.forEach(doses -> assertEquals("recipe " + recipeId, true, doses >= 1 && doses <= 3)));
    }
}

