                .collect(Collectors.toMap(step -> step.getRecipe().getId(), ChainRecipeXp::getXp));

        assertEquals(8.0, xpByRecipe.get(10), 0.0001);
        assertEquals(13.0, xpByRecipe.get(12), 0.0001); // 8 from item 1, 5 from item 3
    }

    @Test
    public void recipeContributionsComeBackInChainOrder() {
        assertEquals(List.of(10, 11, 12), calculate(owned(3, 1, 1, 1)).get(0).getRecipeContributions().stream()
                .map(step -> step.getRecipe().getId())
                .collect(Collectors.toList()));
    }

    @Test
    public void aStepWorthNoXpIsLeftOut() {
        final Recipe freeStep = new Recipe(11, new Ingredient(2, 1), new Ingredient[0],
                new Ingredient(3, 1), RecipeTag.MISC, 0f, 0);

        final RecipeChain chain = new RecipeChain(Arrays.asList(freeStep, THREE_TO_FOUR));

        final List<ChainResult> results = ChainResultCalculator.calculate(List.of(chain), owned(2, 4));

        assertEquals(List.of(12), results.get(0).getRecipeContributions().stream()
                .map(step -> step.getRecipe().getId())
                .collect(Collectors.toList()));
    }

    @Test
    public void outputQuantityCountsOnlyTheProduct() {
        final Recipe threeToFourTriples = new Recipe(12, new Ingredient(3, 1), new Ingredient[0],
                new Ingredient(4, 3), RecipeTag.MISC, 1f, 0);

        final RecipeChain chain = new RecipeChain(Collections.singletonList(threeToFourTriples));

        final List<ChainResult> results = ChainResultCalculator.calculate(List.of(chain), owned(3, 5));

        assertEquals(15.0, results.get(0).getOutputQuantity(), 0.0001);
    }

    @Test
    public void secondaryDemandCoversOnlyTheGroupsOwnRuns() {
        final Recipe needsTwoOfItem50 = new Recipe(12, new Ingredient(3, 1),
                new Ingredient[]{new Ingredient(50, 2)}, new Ingredient(4, 1), RecipeTag.MISC, 1f, 0);

        final RecipeChain chain = new RecipeChain(Collections.singletonList(needsTwoOfItem50));

        final List<ChainResult> results = ChainResultCalculator.calculate(List.of(chain, CHAIN_B), owned(3, 4, 6, 9));

        assertEquals(2, results.size());
        assertEquals(8.0, results.get(0).getSecondaryDemand().get(50), 0.0001);
        assertTrue(results.get(1).getSecondaryDemand().isEmpty());
    }

    /**
     * Grouping splits the work up per chain, so the xp it totals has to match one flat cascade over
     * every recipe at once - nothing lost between chains, nothing counted twice.
     */
    @Test
    public void groupingPerChainLosesNoXpAgainstOneFlatCascade() {
        final Map<Integer, Integer> bank = new HashMap<>();
        bank.put(ItemID.UNIDENTIFIED_RANARR, 40);
        bank.put(ItemID.RANARRVIAL, 25);
        bank.put(ItemID.BRUT_CAVIAR, 12);
        bank.put(ItemID.HARRALANDER_SEED, 3);

        final ItemQuantities owned = ItemQuantities.counted(bank);

        final List<RecipeChain> chains = new RecipeChainResolver(new RecipeGraph(Recipes.all()))
                .resolve(owned, RecipeSelection.ALL_DEFAULT);

        final List<Recipe> everyRecipe = chains.stream()
                .flatMap(chain -> chain.getRecipes().stream())
                .collect(Collectors.toList());

        final double grouped = ChainResultCalculator.calculate(chains, owned).stream()
                .mapToDouble(ChainResult::getXp)
                .sum();

        assertEquals(flatXp(owned, everyRecipe), grouped, 0.0001);
    }

    /**
     * Runs each owned item through every recipe at once, in order, with no notion of chains -
     * deliberately independent of cascade, so the test above compares two different methods.
     */
    private static double flatXp(ItemQuantities owned, List<Recipe> everyRecipe) {
        double xp = 0;

        for (int itemId : owned.itemIds()) {
            final Map<Integer, Double> held = new HashMap<>();
            held.put(itemId, owned.get(itemId));

            for (Recipe recipe : everyRecipe) {
                final double quantity = held.getOrDefault(recipe.getPrimary().getItemId(), 0d);
                if (quantity == 0) continue;

                final double runs = quantity / recipe.getPrimary().getQuantity();
                xp += runs * recipe.getXp();
                held.put(recipe.getOutput().getItemId(), runs * recipe.getOutput().getQuantity());
            }
        }

        return xp;
    }

    // --- cascade ------------------------------------------------------------
    // Its own synthetic table: 1 -> 2 -> 3, and 3 -> 5 taking two at a time and making two.

    private static final Recipe C_ONE_TO_TWO = recipe(10, 1, 1, 2, 1);
    private static final Recipe C_TWO_TO_THREE = recipe(11, 2, 1, 3, 1);
    private static final Recipe C_PAIRS_TO_FIVE = recipe(13, 3, 2, 5, 2);

    @Test
    public void oneRecipeRunsAsOftenAsItsPrimaryAllows() {
        assertRun(cascade(3, 9, C_PAIRS_TO_FIVE).get(0), C_PAIRS_TO_FIVE, 4.5);
    }

    @Test
    public void oneRecipeYieldsItsOutputQuantityPerRun() {
        // 9 of item 3 is 4.5 runs of a recipe making 2 at a time
        assertEquals(9.0, cascade(3, 9, C_PAIRS_TO_FIVE).get(0).getOutputQuantity(), DELTA);
    }

    @Test
    public void producedItemsFeedTheNextRecipe() {
        final List<RecipeRun> runs = cascade(1, 4, C_ONE_TO_TWO, C_TWO_TO_THREE);

        assertEquals(2, runs.size());
        assertRun(runs.get(0), C_ONE_TO_TWO, 4);
        assertRun(runs.get(1), C_TWO_TO_THREE, 4);
    }

    @Test
    public void anItemPartwayAlongStartsWhereItSits() {
        final List<RecipeRun> runs = cascade(2, 4, C_ONE_TO_TWO, C_TWO_TO_THREE);

        assertEquals(1, runs.size());
        assertRun(runs.get(0), C_TWO_TO_THREE, 4);
    }

    @Test
    public void theProductRunsNothing() {
        assertTrue(cascade(3, 5, C_ONE_TO_TWO, C_TWO_TO_THREE).isEmpty());
    }

    @Test
    public void aStoppedRootRunsNothing() {
        assertTrue(ChainResultCalculator.cascade(2, 5, new RecipeChain(2, Collections.emptyList())).isEmpty());
    }

    @Test
    public void anItemOffTheChainRunsNothing() {
        assertTrue(cascade(99, 5, C_ONE_TO_TWO, C_TWO_TO_THREE).isEmpty());
    }

    @Test
    public void runsAreFractionalWhenThePrimaryQuantityDoesNotDivide() {
        assertRun(cascade(3, 3, C_PAIRS_TO_FIVE).get(0), C_PAIRS_TO_FIVE, 1.5);
    }

    @Test
    public void outputQuantityMultipliesThroughTheChain() {
        // one of item 1 makes three of item 2, so the next recipe runs three times
        final Recipe oneToThreeOfTwo = recipe(14, 1, 1, 2, 3);

        final List<RecipeRun> runs = cascade(1, 2, oneToThreeOfTwo, C_TWO_TO_THREE);

        assertRun(runs.get(0), oneToThreeOfTwo, 2);
        assertRun(runs.get(1), C_TWO_TO_THREE, 6);
    }

    @Test
    public void zeroQuantityYieldsNothing() {
        assertTrue(cascade(1, 0, C_ONE_TO_TWO).isEmpty());
    }

    @Test
    public void aFractionalOutputScalesEverythingAfterIt() {
        // item 1 -> 2 succeeds half the time, so 4 of item 1 make 2 of item 2
        final Recipe halfOneToTwo = new Recipe(10, new Ingredient(1, 1), new Ingredient[0],
                new Ingredient(2, 0.5), RecipeTag.MISC, 0f, 0);
        final List<RecipeRun> runs = cascade(1, 4, halfOneToTwo, C_TWO_TO_THREE);

        assertRun(runs.get(0), halfOneToTwo, 4);
        assertEquals(2.0, runs.get(0).getOutputQuantity(), DELTA);
        assertRun(runs.get(1), C_TWO_TO_THREE, 2);
    }

    // --- secondary demand ---------------------------------------------------

    // items 50 and 51 are the secondaries under test
    private static final Recipe NEEDS_ONE_OF_50 = needing(20, 1, new Ingredient(50, 1));
    private static final Recipe NEEDS_TWO_OF_50 = needing(21, 2, new Ingredient(50, 2));
    private static final Recipe NEEDS_BOTH = needing(22, 3, new Ingredient(50, 1), new Ingredient(51, 3));

    @Test
    public void demandIsRunsTimesSecondaryQuantity() {
        assertEquals(12.0, demandOf(run(NEEDS_TWO_OF_50, 6)).get(50), DELTA);
    }

    @Test
    public void demandSumsAcrossRecipes() {
        assertEquals(14.0, demandOf(run(NEEDS_ONE_OF_50, 4), run(NEEDS_TWO_OF_50, 5)).get(50), DELTA);
    }

    @Test
    public void aRecipeCanDemandSeveralSecondaries() {
        final ItemQuantities demand = demandOf(run(NEEDS_BOTH, 2));

        assertEquals(2.0, demand.get(50), DELTA);
        assertEquals(6.0, demand.get(51), DELTA);
    }

    @Test
    public void fractionalRunsDemandFractionally() {
        assertEquals(3.0, demandOf(run(NEEDS_TWO_OF_50, 1.5)).get(50), DELTA);
    }

    @Test
    public void recipesWithoutSecondariesDemandNothing() {
        assertTrue(demandOf(run(C_ONE_TO_TWO, 100)).isEmpty());
    }

    @Test
    public void noRunsDemandNothing() {
        assertTrue(demandOf().isEmpty());
    }

    private static final double DELTA = 0.0001;

    private static List<RecipeRun> cascade(int itemId, int quantity, Recipe... orderedRecipes) {
        return ChainResultCalculator.cascade(itemId, quantity, new RecipeChain(Arrays.asList(orderedRecipes)));
    }

    private static ItemQuantities demandOf(RecipeRun... runs) {
        return ChainResultCalculator.sumSecondaryDemand(Arrays.asList(runs));
    }

    private static RecipeRun run(Recipe recipe, double runs) {
        return new RecipeRun(recipe, runs);
    }

    private static void assertRun(RecipeRun actual, Recipe expected, double runs) {
        assertEquals(expected, actual.getRecipe());
        assertEquals(runs, actual.getRuns(), DELTA);
    }

    private static Recipe recipe(int id, int primaryId, int primaryQty, int outputId, int outputQty) {
        return new Recipe(id, new Ingredient(primaryId, primaryQty), new Ingredient[0],
                new Ingredient(outputId, outputQty), RecipeTag.MISC, 0f, 0);
    }

    private static Recipe needing(int id, int primaryId, Ingredient... secondaries) {
        return new Recipe(id, new Ingredient(primaryId, 1), secondaries,
                new Ingredient(primaryId + 100, 1), RecipeTag.MISC, 0f, 0);
    }

    private static List<ChainResult> calculate(ItemQuantities owned) {
        return ChainResultCalculator.calculate(List.of(CHAIN_A, CHAIN_B), owned);
    }

    private static ItemQuantities owned(int... pairs) {
        final Map<Integer, Integer> items = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2) {
            items.put(pairs[i], pairs[i + 1]);
        }
        return ItemQuantities.counted(items);
    }

    private static Recipe recipe(int id, int primary, int output) {
        return new Recipe(id, new Ingredient(primary, 1), new Ingredient[0],
                new Ingredient(output, 1), RecipeTag.MISC, 1f, 0);
    }
}

package adamski.domain.result;

import adamski.domain.Ingredient;
import adamski.domain.ItemQuantities;
import adamski.domain.Recipe;
import adamski.domain.RecipeTag;
import adamski.domain.route.RecipeChain;
import org.junit.Test;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.UnaryOperator;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertSame;

public class RecipeModifiersTest {
    private static final double DELTA = 1e-9;

    private static final int PRIMARY = 1;
    private static final int SECONDARY = 2;
    private static final int OUTPUT = 3;

    /**
     * 1 primary and 2 secondaries make 1 output, worth 10xp a run.
     */
    private static final Recipe MIX = new Recipe(10, new Ingredient(PRIMARY, 1),
            new Ingredient[]{new Ingredient(SECONDARY, 2)}, new Ingredient(OUTPUT, 1), RecipeTag.POTION, 10f, 0);

    // --- the chain walk ----------------------------------------------

    @Test
    public void modifiersRunInListOrder() {
        final UnaryOperator<Recipe> doubleOutput = recipe -> recipe.withOutputQuantity(recipe.getOutput().getQuantity() * 2);
        final UnaryOperator<Recipe> setOutput = recipe -> recipe.withOutputQuantity(5);

        assertEquals(10.0, outputOf(List.of(setOutput, doubleOutput)), DELTA);
        assertEquals(5.0, outputOf(List.of(doubleOutput, setOutput)), DELTA);
    }

    @Test
    public void aStoppedChainKeepsItsRoot() {
        final RecipeChain stopped = new RecipeChain(5, Collections.emptyList());

        final List<RecipeChain> applied = RecipeModifiers.apply(List.of(stopped),
                List.of(RecipeModifiers.outputOverrides(Map.of(10, 0.85))));

        assertEquals(5, applied.get(0).getRootItemId());
    }

    // --- output overrides --------------------------------------------

    @Test
    public void anOverrideReplacesItsRecipesOutput() {
        final Recipe overridden = RecipeModifiers.outputOverrides(Map.of(10, 0.85)).apply(MIX);

        assertEquals(0.85, overridden.getOutput().getQuantity(), DELTA);
        assertEquals(OUTPUT, overridden.getOutput().getItemId());
    }

    @Test
    public void aRecipeWithNoOverrideIsLeftAlone() {
        assertSame(MIX, RecipeModifiers.outputOverrides(Map.of(99, 0.85)).apply(MIX));
    }

    @Test
    public void anOverrideChangesTheOutputButNotTheXp() {
        final ChainResult result = calculate(RecipeModifiers.outputOverrides(Map.of(10, 0.25)), 10);

        assertEquals(2.5, result.getOutputQuantity(), DELTA);
        assertEquals(100.0, result.getXp(), DELTA); // the attempts still run
    }

    // --- input scaling ----------------------------------------------

    @Test
    public void scalingThePrimaryDownMakesMoreFromWhatIsBanked() {
        final ChainResult result = calculate(RecipeModifiers.inputScaling(Map.of(10, Set.of(PRIMARY)), 0.9), 9);

        assertEquals(10.0, result.getOutputQuantity(), DELTA); // 9 / 0.9 runs
        assertEquals(100.0, result.getXp(), DELTA);
        assertEquals(20.0, result.getSecondaryDemand().get(SECONDARY), DELTA); // more runs, more secondaries
    }

    @Test
    public void scalingASecondaryChangesDemandButNotXp() {
        final ChainResult result = calculate(RecipeModifiers.inputScaling(Map.of(10, Set.of(SECONDARY)), 0.9), 10);

        assertEquals(10.0, result.getOutputQuantity(), DELTA);
        assertEquals(100.0, result.getXp(), DELTA);
        assertEquals(18.0, result.getSecondaryDemand().get(SECONDARY), DELTA);
    }

    @Test
    public void aRecipeWithNothingListedIsLeftAlone() {
        assertSame(MIX, RecipeModifiers.inputScaling(Map.of(99, Set.of(PRIMARY)), 0.9).apply(MIX));
    }

    @Test(expected = IllegalArgumentException.class)
    public void scalingAnItemTheRecipeDoesNotUseIsAnError() {
        RecipeModifiers.inputScaling(Map.of(10, Set.of(OUTPUT)), 0.9).apply(MIX);
    }

    // --- output scaling ---------------------------------------------

    @Test
    public void outputScalingMultipliesWhatARunMakesButUsesNothingMore() {
        final ChainResult result = calculate(RecipeModifiers.outputScaling(Map.of(10, 1.15)), 10);

        assertEquals(11.5, result.getOutputQuantity(), DELTA);
        assertEquals(100.0, result.getXp(), DELTA); // no extra xp for the extra dose
        assertEquals(20.0, result.getSecondaryDemand().get(SECONDARY), DELTA);
    }

    @Test
    public void outputScalingScalesAnOverrideRatherThanReplacingIt() {
        assertEquals(0.5 * 1.15, outputOf(List.of(
                RecipeModifiers.outputOverrides(Map.of(10, 0.5)),
                RecipeModifiers.outputScaling(Map.of(10, 1.15)))), DELTA);
    }

    @Test
    public void aRecipeWithNoFactorIsLeftAlone() {
        assertSame(MIX, RecipeModifiers.outputScaling(Map.of(99, 1.15)).apply(MIX));
    }

    // --- xp scaling --------------------------------------------------

    @Test
    public void xpScalingScalesOnlyTheXpOfTaggedRecipes() {
        final ChainResult result = calculate(RecipeModifiers.xpScaling(RecipeTag.POTION, 0.5), 10);

        assertEquals(50.0, result.getXp(), DELTA);
        assertEquals(10.0, result.getOutputQuantity(), DELTA);
        assertEquals(20.0, result.getSecondaryDemand().get(SECONDARY), DELTA);
    }

    @Test
    public void xpScalingLeavesOtherTagsAlone() {
        assertSame(MIX, RecipeModifiers.xpScaling(RecipeTag.DEGRIME, 0).apply(MIX));
    }

    // --- runs ---------------------------------------------------------

    @Test
    public void aChainSaysWhetherItRunsARecipe() {
        final ChainResult result = calculate(UnaryOperator.identity(), 10);

        assertTrue(result.runsAnyOf(Set.of(10, 99)));
        assertFalse(result.runsAnyOf(Set.of(99)));
    }

    private static double outputOf(List<UnaryOperator<Recipe>> modifiers) {
        return RecipeModifiers.apply(List.of(new RecipeChain(List.of(MIX))), modifiers)
                .get(0).getRecipes().get(0).getOutput().getQuantity();
    }

    private static ChainResult calculate(UnaryOperator<Recipe> modifier, double banked) {
        final List<RecipeChain> chains = RecipeModifiers.apply(List.of(new RecipeChain(List.of(MIX))), List.of(modifier));

        return ChainResultCalculator.calculate(chains, ItemQuantities.of(Map.of(PRIMARY, banked))).get(0);
    }
}

package adamski.domain.route;

import adamski.domain.Ingredient;
import adamski.domain.ItemQuantities;
import adamski.domain.Recipe;
import adamski.domain.RecipeTag;

import org.junit.Test;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * Synthetic recipes: 1 -> 2 -> 3 -> 4, with 3 also able to make 5, and a stranded 6 -> 7.
 */
public class RecipeChainResolverTest {
    private static final Recipe ONE_TO_TWO = recipe(10, 1, 2);
    private static final Recipe TWO_TO_THREE = recipe(11, 2, 3);
    private static final Recipe THREE_TO_FOUR = recipe(12, 3, 4);
    private static final Recipe THREE_TO_FIVE = recipe(13, 3, 5, 13);
    private static final Recipe SIX_TO_SEVEN = recipe(14, 6, 7);

    private static final RecipeGraph GRAPH = new RecipeGraph(
            Arrays.asList(ONE_TO_TWO, TWO_TO_THREE, THREE_TO_FOUR, THREE_TO_FIVE, SIX_TO_SEVEN));

    private static final RecipeChainResolver RESOLVER = new RecipeChainResolver(GRAPH);

    @Test
    public void oneBankedItemIsOneChain() {
        final List<RecipeChain> chains = calculate(owned(1, 10));

        assertEquals(1, chains.size());
        assertEquals(1, chains.get(0).getRootItemId());
        assertEquals(4, chains.get(0).getProductItemId()); // first option all the way down
    }

    @Test
    public void anythingAlongTheChainJoinsIt() {
        final List<RecipeChain> chains = calculate(owned(1, 10, 2, 5, 3, 8));

        assertEquals(1, chains.size());
        assertEquals(1, chains.get(0).getRootItemId());
    }

    @Test
    public void theLeastMatureItemRootsTheChain() {
        assertEquals(1, calculate(owned(3, 8, 1, 10)).get(0).getRootItemId());
    }

    @Test
    public void anItemThatCannotReachTheProductRootsItsOwnChain() {
        final List<RecipeChain> chains = calculate(owned(1, 10, 6, 4));

        assertEquals(2, chains.size());
        assertEquals(List.of(1, 6), chains.stream()
                .map(RecipeChain::getRootItemId)
                .collect(Collectors.toList()));
    }

    @Test
    public void anItemDownstreamOfTheChosenProductStrandsIntoItsOwnChain() {
        // stop at item 2
    final List<RecipeChain> chains = RESOLVER.resolve(owned(1, 10, 3, 5), stopAt(2));

        assertEquals(2, chains.size());
        assertEquals(2, chains.get(0).getProductItemId());
        assertEquals(3, chains.get(1).getRootItemId());
    }

    /**
     * The pile of item 1 has been used up, so the cut now lands on the item rooting the chain. It
     * makes nothing, but it is still a chain - its row is the only place left to undo the cut.
     */
    @Test
    public void aChainCutWhereItsRootStandsIsStillAChain() {
        final List<RecipeChain> chains = RESOLVER.resolve(owned(2, 10), stopAt(2));

        assertEquals(1, chains.size());
        assertEquals(2, chains.get(0).getRootItemId());
        assertEquals(2, chains.get(0).getProductItemId());
        assertTrue(chains.get(0).getRecipes().isEmpty());
    }

    @Test
    public void anItemBelowACutThatHasBeenReachedRootsItsOwnChain() {
        // the chain is cut at item 2 and the pile of item 1 is gone, so item 3 is left to itself
        final List<RecipeChain> chains = RESOLVER.resolve(owned(2, 10, 3, 5), stopAt(2));

        assertEquals(2, chains.size());
        assertEquals(3, chains.get(1).getRootItemId());
        assertEquals(4, chains.get(1).getProductItemId());
        assertEquals(List.of(12), chains.get(1).getRecipes().stream()
                .map(Recipe::getId)
                .collect(Collectors.toList()));
    }

    /**
     * The panel orders rows of one family by this - seed before grimy before unf.
     */
    @Test
    public void chainsComeBackLeastMatureRootFirst() {
        final List<Integer> roots = RESOLVER.resolve(owned(3, 8, 6, 4), stopAt(2)).stream()
                .map(RecipeChain::getRootItemId)
                .collect(Collectors.toList());

        final List<Integer> byMaturity = roots.stream()
                .sorted(java.util.Comparator.comparingInt(GRAPH::maturityOf))
                .collect(Collectors.toList());

        assertEquals(2, roots.size());
        assertEquals(byMaturity, roots);
    }

    @Test
    public void anItemThatMakesNothingIsNoChain() {
        assertTrue(calculate(owned(4, 100)).isEmpty());
    }

    @Test
    public void choosingTheProductChoosesTheChain() {
        final List<RecipeChain> chains = RESOLVER.resolve(owned(1, 10), choose(3, 13));

        assertEquals(List.of(10, 11, 13), chains.get(0).getRecipes().stream()
                .map(Recipe::getId)
                .collect(Collectors.toList()));
    }

    @Test
    public void theChainsTogetherCoverEveryRecipe() {
        final List<Recipe> recipes = recipesOf(calculate(owned(1, 10, 6, 4)));

        assertEquals(Set.of(10, 11, 12, 14), recipes.stream()
                .map(Recipe::getId)
                .collect(Collectors.toSet()));
    }

    @Test
    public void chainOrderRunsProducersBeforeConsumers() {
        final List<Recipe> recipes = recipesOf(calculate(owned(1, 10, 6, 4)));

        for (int earlier = 0; earlier < recipes.size(); earlier++) {
            for (int later = earlier + 1; later < recipes.size(); later++) {
                assertNotEquals("a consumer runs before its producer",
                        recipes.get(later).getOutput().getItemId(),
                        recipes.get(earlier).getPrimary().getItemId());
            }
        }
    }

    @Test
    public void noPrimaryIsClaimedTwice() {
        final List<Recipe> recipes = recipesOf(calculate(owned(1, 10, 2, 5, 3, 8)));

        assertEquals(recipes.size(), recipes.stream()
                .map(recipe -> recipe.getPrimary().getItemId())
                .distinct()
                .count());
    }

    /**
     * What ChainResultCalculator.cascade does with the chains it is given.
     */
    private static List<Recipe> recipesOf(List<RecipeChain> chains) {
        return chains.stream()
                .flatMap(chain -> chain.getRecipes().stream())
                .collect(Collectors.toList());
    }

    private static List<RecipeChain> calculate(ItemQuantities owned) {
        return RESOLVER.resolve(owned, RecipeSelection.ALL_DEFAULT);
    }

    /**
     * One item told to make nothing, so the chain ends there and anything below it is left over.
     */
    private static RecipeSelection stopAt(int itemId) {
        return RecipeSelection.of(Map.of(itemId, RecipeSelection.STOP));
    }

    /**
     * One item told to take a recipe other than the first the table offers.
     */
    private static RecipeSelection choose(int itemId, int recipeId) {
        return RecipeSelection.of(Map.of(itemId, recipeId));
    }

    private static ItemQuantities owned(int... pairs) {
        final Map<Integer, Integer> items = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2) {
            items.put(pairs[i], pairs[i + 1]);
        }
        return ItemQuantities.counted(items);
    }

    private static Recipe recipe(int id, int primary, int output) {
        return recipe(id, primary, output, 0);
    }

    private static Recipe recipe(int id, int primary, int output, int level) {
        return new Recipe(id, new Ingredient(primary, 1), new Ingredient[0],
                new Ingredient(output, 1), RecipeTag.MISC, 1f, level);
    }
}

package adamski.domain.route;

